const seed=()=>({priorities:[],targets:{},roots:{},custom:{},activities:[],status:'Draf',budget:'Belum diisi',progress:{},evaluation:{},follow:{},year:'2027/2028'});
let data;try{data=JSON.parse(localStorage.getItem('spmp-rkt-spreadsheet-v3'))||seed()}catch{data=seed()}
let history;try{history=JSON.parse(localStorage.getItem('spmp-history-spreadsheet-v3'))||[]}catch{history=[]}
function migrateCycleStatus(cycle){if(!cycle)return;const wasActive=['Aktif','Sudah ada rencana','Disetujui','Menunggu persetujuan'].includes(cycle.status);if(cycle.status!=='Selesai')cycle.status=wasActive||Object.values(cycle.planSaved||{}).some(Boolean)?'Sudah ada rencana':'Draf';delete cycle.revisionKind;}
migrateCycleStatus(data);history.forEach(migrateCycleStatus);localStorage.setItem('spmp-rkt-spreadsheet-v3',JSON.stringify(data));localStorage.setItem('spmp-history-spreadsheet-v3',JSON.stringify(history));
if(['Draf','Perlu revisi'].includes(data.status)){const legacy=data.activities.filter(a=>a.id==='sample-'+a.indicator&&!a.recommendationKey);if(legacy.length){data.activities=data.activities.filter(a=>!legacy.includes(a));data.planSaved={};localStorage.setItem('spmp-rkt-spreadsheet-v3',JSON.stringify(data))}}
const period=()=>{let y=Number(data.year.split('/')[0]);return `Juli ${y} – Juni ${y+1}`};
let page='rapor',stage=0,tab='Semua sumber',demo=false,toastTimer;
const ind=id=>indicators.find(i=>i.id===id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
function save(){localStorage.setItem('spmp-rkt-spreadsheet-v3',JSON.stringify(data));const el=$('.save');if(el)el.textContent='✓ '+(stage<3?'Draf':'Perubahan')+' tersimpan otomatis';}
function toast(t){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast" role="status">${esc(t)}</div>`);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast')?.remove(),3500)}
function badge(t){return `<span class="badge ${t==='Sudah ada rencana'||t==='Disetujui'||t==='Selesai'?'green':t.startsWith('Perlu revisi')?'red':t.includes('Menunggu')?'amber':'blue'}">${esc(t)}</span>`}
const reflectionRubrics=[{"question": "Bagaimana satuan pendidikan menetapkan indikator prioritas dan target peningkatan mutunya?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Sebagian indikator prioritas sudah dipilih, target belum lengkap atau belum terukur.", "Setiap indikator prioritas punya baseline dan target tahunan yang terukur, disepakati TPMPS.", "Target ditinjau ulang berdasarkan hasil evaluasi siklus sebelumnya dan tren data."]}, {"question": "Bagaimana satuan pendidikan memetakan masalah dan menganalisis akar masalah pada indikator prioritas?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Masalah teridentifikasi pada sebagian prioritas, akar masalah masih dugaan.", "Setiap prioritas punya akar masalah yang ditunjang data Rapor atau data sekolah.", "Akar masalah ditelusuri lintas lapis (pengelolaan, guru, pembelajaran) dengan metode yang tercatat."]}, {"question": "Bagaimana program, kegiatan, dan anggaran disusun untuk menjawab masalah mutu?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Kegiatan disusun, tetapi belum semuanya menjawab akar masalah.", "Setiap kegiatan tertaut ke akar masalah dan setiap prioritas punya kegiatan.", "Setiap kegiatan berbiaya tercantum di RKAS dan setiap baris belanja dapat ditelusuri ke prioritas."]}, {"question": "Sejauh mana kegiatan peningkatan mutu terlaksana sesuai rencana?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Sebagian kegiatan berjalan, bukti pelaksanaan masih sedikit.", "Mayoritas kegiatan berjalan sesuai jadwal dengan bukti yang sudah ada.", "Hampir semua kegiatan terlaksana, dipantau berkala, dan buktinya lengkap."]}, {"question": "Bagaimana sekolah menilai efektivitas kegiatan dan ketercapaian output?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Evaluasi dilakukan pada sebagian kegiatan, belum membandingkan target.", "Setiap kegiatan dievaluasi terhadap target output.", "Evaluasi memakai data capaian (output dan perubahan indikator) untuk menilai efektivitas."]}, {"question": "Bagaimana hasil evaluasi menjadi dasar perbaikan siklus berikutnya?", "levels": ["Tahap ini belum dijalani pada siklus ini.", "Ada tindak lanjut untuk sebagian temuan evaluasi.", "Setiap kegiatan yang kurang efektif memiliki tindakan korektif atau preventif.", "Tindak lanjut masuk ke RKT berikutnya atau mengubah target, dan dipantau."]}];
let reflectionYear='',reflectionStep=0;
let reflections;try{reflections=JSON.parse(localStorage.getItem('spmp-self-reflections-v1'))||{}}catch{reflections={}}
function completedReflectionCycles(){const all=[data,...history,sampleArchive()].filter(r=>r.status==='Selesai');return all.filter((r,i)=>all.findIndex(x=>x.year===r.year)===i).sort((a,b)=>b.year.localeCompare(a.year))}
function reflectionSave(){localStorage.setItem('spmp-self-reflections-v1',JSON.stringify(reflections))}
function selectReflectionCycle(year){if(!completedReflectionCycles().some(r=>r.year===year))return;reflectionYear=year;reflections[year]??={scores:{},notes:{},completed:false};const r=reflections[year];reflectionStep=r.completed?6:reflectionRubrics.findIndex((_,i)=>r.scores[i]===undefined);if(reflectionStep<0)reflectionStep=6;render()}
function reflectionChoose(score){if(!completedReflectionCycles().some(r=>r.year===reflectionYear)||reflectionStep>5)return;const r=reflections[reflectionYear];if(r.completed)return;r.scores[reflectionStep]=score;r.completed=false;reflectionSave();render()}
function reflectionNote(value){if(reflections[reflectionYear]?.completed)return;reflections[reflectionYear].notes[reflectionStep]=value;reflectionSave()}
function reflectionNext(){const r=reflections[reflectionYear];if(r.scores[reflectionStep]===undefined)return toast('Pilih penilaian untuk tahap ini terlebih dahulu.');const scrollPosition=window.scrollY;reflectionStep++;render();window.scrollTo({top:scrollPosition,left:0,behavior:'instant'})}
function finishReflection(){const r=reflections[reflectionYear];if(!r||r.completed)return;if(reflectionRubrics.some((_,i)=>r.scores[i]===undefined))return toast('Lengkapi penilaian keenam tahap terlebih dahulu.');const cycle=completedReflectionCycles().find(c=>c.year===reflectionYear);if(!cycle)return;const ev=reflectionEvidence(cycle);const missing=reflectionRubrics.findIndex((_,i)=>r.scores[i]!==ev[i].score&&!r.justifications?.[i]?.trim());if(missing>=0){toast('Lengkapi alasan perbedaan penilaian pada tahap '+names[missing]+'.');document.getElementById('reflection-justification-'+missing)?.focus();return}r.completed=true;r.evidenceSnapshot=ev;r.savedAt=new Date().toISOString();reflectionSave();reflectionList();toast('Evaluasi diri tersimpan.')}
function reflectionList(){reflectionYear='';reflectionStep=0;render();window.scrollTo(0,0)}
function selfEvaluation(){const cycles=completedReflectionCycles(),labels=['Belum','Rintisan','Berkembang','Mandiri'];if(!cycles.some(c=>c.year===reflectionYear))reflectionYear='';if(reflectionYear)return `<button class="quiet" onclick="reflectionList()">← Kembali ke daftar evaluasi diri</button><div class="eyebrow">Siklus ${esc(reflectionYear)}</div><h1>Evaluasi Diri</h1><p class="muted">Refleksikan cara sekolah menjalani setiap tahap untuk memperbaiki siklus berikutnya.</p>${reflectionStep===6?reflectionSummary(labels):reflectionQuestion(labels)}`;return `<div class="eyebrow">Belajar dari perjalanan sekolah</div><h1>Evaluasi Diri</h1><p class="muted">Refleksikan siklus yang sudah selesai. Mulai penilaian, lanjutkan draf, atau lihat hasil refleksi sebelumnya.</p>${!cycles.length?'<div class="card"><h2>Belum ada siklus yang selesai</h2><p>Evaluasi diri tersedia setelah sekolah menyelesaikan satu Siklus 6M.</p><button onclick="go(&quot;home&quot;)">Lihat siklus sekolah</button></div>':`<div class="card reflection-list-card"><div class="table-scroll"><table class="reflection-list"><thead><tr><th>Siklus</th><th>Progres refleksi</th><th>Status</th><th class="reflection-list-action">Tindakan</th></tr></thead><tbody>${cycles.map(c=>{const r=reflections[c.year],count=reflectionRubrics.filter((_,i)=>r?.scores[i]!==undefined).length,status=r?.completed?'Selesai':count?'Draf':'Belum dimulai';return `<tr><td><b>Siklus ${esc(c.year)}</b><small>Juli ${esc(c.year.split('/')[0])} – Juni ${esc(c.year.split('/')[1])}</small></td><td>${count} dari 6 tahap</td><td>${badge(status)}</td><td class="reflection-list-action"><button class="${r?.completed?'':'primary'}" onclick="selectReflectionCycle('${c.year}')">${r?.completed?'Lihat hasil':count?'Lanjutkan':'Mulai evaluasi diri'}</button></td></tr>`}).join('')}</tbody></table></div></div>`}`}

function reflectionQuestion(labels){const r=reflections[reflectionYear],q=reflectionRubrics[reflectionStep];return `<article class="card reflection-question"><div class="row reflection-progress-heading"><div class="reflection-stage-title">${names[reflectionStep]} <span>· Tahap ${reflectionStep+1} dari 6</span></div><span class="sub">✓ Tersimpan otomatis</span></div><div class="reflection-dots" aria-label="Progres refleksi">${names.map((n,i)=>`<span class="${i===reflectionStep?'current':r.scores[i]!==undefined?'filled':''}" aria-label="${esc(n)}"></span>`).join('')}</div><h2>${q.question}</h2><div class="reflection-options" role="group" aria-label="Penilaian ${names[reflectionStep]}">${labels.map((label,i)=>`<button type="button" aria-pressed="${r.scores[reflectionStep]===i}" onclick="reflectionChoose(${i})"><b>${label}</b><span>${esc(q.levels[i])}</span></button>`).join('')}</div><div class="actions"><button ${reflectionStep===0?'disabled':''} onclick="reflectionStep--;render()">← Sebelumnya</button><button class="primary" onclick="reflectionNext()">${reflectionStep===5?'Tinjau penilaian':'Lanjut'} →</button></div></article>`}
function reflectionEvidence(cycle){const P=cycle.priorities||[],K=cycle.activities||[],roots=cycle.roots||{},progress=cycle.progress||{},evaluation=cycle.evaluation||{},follow=cycle.follow||{};const result=[];const add=(score,reasons)=>result.push({score,reasons});const targets=P.filter(id=>typeof ind(id)?.score==='number'&&Number(cycle.targets?.[id])>0).length;
add(!P.length?0:targets<P.length||!cycle.teamAgreement?1:cycle.targetsReviewed?3:2,[`${P.length} indikator prioritas ditetapkan.`,`${targets} dari ${P.length} prioritas memiliki capaian awal dan target tercatat.`,cycle.teamAgreement?'Kesepakatan tim tercatat.':'Kesepakatan TPMPS belum tercatat di prototipe.',cycle.targetsReviewed?'Peninjauan target dari evaluasi sebelumnya tercatat.':'Peninjauan target dari evaluasi sebelumnya belum tercatat.','Referensi menggunakan target 4 tahun; prototipe saat ini belum mengumpulkannya.']);
const mapped=P.filter(id=>roots[id]?.length).length;const deep=P.filter(id=>cycle.rootAnalysis?.[id]?.method&&cycle.rootAnalysis[id].layers?.length>=2).length;
add(!mapped?0:mapped<P.length?1:deep===P.length?3:2,[`${mapped} dari ${P.length} prioritas memiliki akar masalah.`,`${deep} dari ${P.length} prioritas memiliki analisis lintas lapis dan metode tercatat.`]);
const linked=K.filter(a=>a.root&&(roots[a.indicator]||[]).includes(a.root)).length,covered=P.filter(id=>K.some(a=>a.indicator===id)).length,costed=K.filter(a=>a.needsBudget===true||Number(a.budget)>0),budgetComplete=costed.filter(a=>(a.budgetLines||[]).some(r=>r.description?.trim()&&r.month&&Number(r.quantity)>0&&r.unit?.trim()&&r.price!==''&&Number.isFinite(Number(r.price)))).length;
add(!K.length?0:linked<K.length||covered<P.length?1:budgetComplete===costed.length&&cycle.budgetChecksPassed===true?3:2,[`${linked} dari ${K.length} kegiatan terhubung dengan akar masalah.`,`${covered} dari ${P.length} prioritas memiliki kegiatan.`,`${budgetComplete} dari ${costed.length} kegiatan beranggaran memiliki rincian lengkap.`,cycle.budgetChecksPassed?'Pemeriksaan rancangan RKAS tercatat.':'Pemeriksaan batas komponen RKAS/BOSP belum tersedia; rincian anggaran tidak dianggap sebagai bukti persetujuan ARKAS.']);
const run=K.filter(a=>{const p=progress[a.id]||{};return p.notes?.trim()||p.link?.trim()||p.files?.length||Number(p.achieved)>0}).length,proof=K.filter(a=>progress[a.id]?.link?.trim()||progress[a.id]?.files?.length).length,ratio=K.length?proof/K.length:0,monitoring=cycle.monitoring?.length||0;
add(!run?0:ratio<.5?1:ratio>=.8&&monitoring>=2?3:2,[`${run} dari ${K.length} kegiatan memiliki catatan atau aktivitas pelaksanaan.`,`${proof} dari ${K.length} kegiatan memiliki tautan atau lampiran bukti.`,`${monitoring} catatan monitoring berkala tercatat.`]);
const evaluated=K.filter(a=>evaluation[a.id]?.result).length;
add(!evaluated?0:evaluated<K.length?1:2,[`${evaluated} dari ${K.length} kegiatan memiliki penilaian efektivitas.`,`${K.length-evaluated} kegiatan belum dievaluasi.`,'Prototipe tidak lagi mengumpulkan target output numerik; hasil ini memakai penilaian efektivitas yang tercatat. Perubahan indikator antarsiklus belum dinilai otomatis.']);
const needs=K.filter(a=>['Perlu penyesuaian','Tidak efektif'].includes(evaluation[a.id]?.result)),actions=K.filter(a=>follow[a.id]?.action?.trim()),addressed=needs.filter(a=>follow[a.id]?.action?.trim()).length,carry=actions.some(a=>follow[a.id]?.carry);
add(!actions.length?0:addressed<needs.length?1:carry?3:2,[`${actions.length} kegiatan memiliki rencana tindak lanjut.`,`${addressed} dari ${needs.length} kegiatan yang perlu perbaikan memiliki tindak lanjut.`,carry?'Ada tindak lanjut yang dibawa ke siklus berikutnya.':'Belum ada tindak lanjut yang dibawa ke siklus berikutnya.']);return result}
function reflectionComparisonStatus(self,evidence){return self===evidence?'Konsisten':self>evidence?'Di atas penilaian berdasarkan bukti':'Di bawah penilaian berdasarkan bukti'}
function reviewReflectionScore(index,value){const r=reflections[reflectionYear],scroll=window.scrollY;if(!r||r.completed)return;r.scores[index]=Number(value);r.completed=false;reflectionSave();render();window.scrollTo({top:scroll,left:0,behavior:'instant'})}
function reflectionJustify(index,value){const r=reflections[reflectionYear];if(!r||r.completed)return;r.justifications??={};r.justifications[index]=value;r.completed=false;reflectionSave();const status=document.getElementById('reflection-review-save-status');if(status)status.textContent='Draf tersimpan otomatis';const button=document.getElementById('reflection-review-save');if(button)button.hidden=false}
function reflectionSummary(labels){const r=reflections[reflectionYear],cycle=completedReflectionCycles().find(c=>c.year===reflectionYear);if(!cycle)return '';const ev=r.completed&&r.evidenceSnapshot?r.evidenceSnapshot:reflectionEvidence(cycle),different=names.map((_,i)=>i).filter(i=>r.scores[i]!==ev[i].score);const basis=i=>`<details class="reflection-evidence-details"><summary>Lihat dasar penilaian</summary><ul>${ev[i].reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul>${r.notes[i]?`<p class="sub">Catatan refleksi Anda: ${esc(r.notes[i])}</p>`:''}</details>`;return `<article class="card reflection-summary reflection-focus-review"><span class="tag">${r.completed?'Evaluasi diri tersimpan':'Tinjau Evaluasi Diri'}</span><h2>Refleksi Siklus ${esc(reflectionYear)}</h2><p class="sub">Bandingkan penilaian Anda dengan bukti aktivitas yang tercatat. Tingkat berdasarkan bukti tidak menggantikan penilaian sekolah.</p><div class="notice">${different.length?`${different.length} tahap memiliki perbedaan penilaian. ${r.completed?'Alasan penilaian tersimpan di bawah tahap terkait.':'Lengkapi alasan untuk setiap penilaian yang lebih tinggi maupun lebih rendah.'}`:'Seluruh penilaian diri konsisten dengan bukti yang tercatat.'}</div><div class="table-scroll"><table class="reflection-comparison-table"><thead><tr><th>Tahap</th><th>Penilaian Anda</th><th>Berdasarkan bukti</th></tr></thead><tbody>${names.map((name,i)=>`<tr><td><b>${name}</b></td><td>${r.completed?`<b>${labels[r.scores[i]]}</b>`:`<select aria-label="Penilaian diri ${name}" onchange="reviewReflectionScore(${i},this.value)">${labels.map((label,j)=>`<option value="${j}" ${r.scores[i]===j?'selected':''}>${label}</option>`).join('')}</select>`}</td><td><b>${labels[ev[i].score]}</b></td></tr>${r.scores[i]!==ev[i].score?`<tr class="reflection-justification-row"><td colspan="3"><section class="reflection-difference-entry"><label for="reflection-justification-${i}">Mengapa Anda memilih ${labels[r.scores[i]]}, sementara bukti menunjukkan ${labels[ev[i].score]}?</label>${r.completed?`<p class="reflection-saved-reason">${esc(r.justifications?.[i]||'—')}</p>`:`<textarea required aria-required="true" id="reflection-justification-${i}" oninput="reflectionJustify(${i},this.value)" placeholder="Jelaskan pertimbangan atau konteks sekolah.">${esc(r.justifications?.[i]||'')}</textarea>`}${basis(i)}</section></td></tr>`:''}`).join('')}</tbody></table></div>${different.length<6?`<details class="reflection-consistent-details"><summary>Lihat dasar penilaian tahap yang konsisten</summary>${names.map((name,i)=>r.scores[i]===ev[i].score?`<section><h3>${name}</h3>${basis(i)}</section>`:'').join('')}</details>`:''}<p class="source-text">Penilaian berdasarkan data yang tercatat di prototipe. Unsur rubrik yang belum dikumpulkan ditandai pada dasar penilaian dan tidak diasumsikan terpenuhi.</p><div class="actions">${r.completed?'<button onclick="reflectionList()">← Kembali ke daftar evaluasi diri</button>':'<button onclick="reflectionStep=5;render()">← Kembali</button>'}<span id="reflection-review-save-status" class="sub">${r.completed?'✓ Evaluasi diri telah tersimpan':'✓ Draf tersimpan otomatis'}</span><button id="reflection-review-save" class="primary" ${r.completed?'hidden':''} onclick="finishReflection()">Simpan evaluasi diri</button></div></article>`}

function mainNavbar(){return `<header class="platform-navbar"><details class="navbar-identity"><summary><span class="emblem" aria-hidden="true"><img src="assets/nav/logo-kemendikbud.png" alt=""></span><span class="navbar-brand-copy"><b>Platform SPMP</b><span>SMA Rakyat 3</span></span><img class="navbar-chevron" src="assets/nav/arrow-down.svg" width="24" height="24" alt="" aria-hidden="true"></summary><div class="navbar-dropdown"><b>SMA Rakyat 3</b><p>NPSN 20260001</p><span>Identitas sekolah demonstrasi</span></div></details><nav aria-label="Navigasi utama"><button class="${['rapor','rapor-root','diagnosis-alternatives'].includes(page)?'active':''}" ${['rapor','rapor-root','diagnosis-alternatives'].includes(page)?'aria-current="page"':''} onclick="go('rapor')">Diagnosis</button><button class="${['home','flow','review','detail','menetapkan-alternative','menetapkan-cards'].includes(page)?'active':''}" ${['home','flow','review','detail'].includes(page)?'aria-current="page"':''} onclick="go('home')">Siklus 6M</button><button class="${page==='self-evaluation'?'active':''}" ${page==='self-evaluation'?'aria-current="page"':''} onclick="go('self-evaluation')">Evaluasi Diri</button><button class="${page==='downloads'?'active':''}" ${page==='downloads'?'aria-current="page"':''} onclick="go('downloads')">Unduh</button></nav><details class="navbar-account"><summary aria-label="Menu akun sekolah"><span class="avatar">SR</span><img class="navbar-chevron" src="assets/nav/arrow-down.svg" width="24" height="24" alt="" aria-hidden="true"></summary><div class="navbar-dropdown"><b>Akun satuan pendidikan</b><p>SMA Rakyat 3</p><span>Prototipe demonstrasi</span><div class="navbar-profile-menu"><button type="button" disabled>Glosarium</button></div></div></details></header>`}

function pageTitleBanner(){if(page==='rapor'||page==='rapor-root')return '';let title='Diagnosis',description='Kenali kondisi mutu sekolah melalui capaian indikator dan telusuri area yang perlu diperbaiki.',context='SMA Rakyat 3 · Tahun data 2025';if(page==='menetapkan-cards'){title=headings[0];description=descriptions[0];context='Design alternatives 2 · Menetapkan · Siklus '+data.year}else if(page==='menetapkan-alternative'){title=headings[0];description=descriptions[0];context='Alternatif desain · Menetapkan lama · Siklus '+data.year}else if(page==='home'){title='Siklus 6M';description='Susun dan jalankan langkah perbaikan sekolah, lalu gunakan hasil evaluasi untuk siklus berikutnya.';context='Tahun ajaran '+data.year}else if(page==='flow'){title=headings[stage];description=descriptions[stage];context='Siklus '+data.year+' · '+names[stage]}else if(page==='review'){title='Tinjau arah perbaikan sekolah';description='Pastikan prioritas, akar masalah, dan kegiatan saling terhubung sebelum rencana disimpan.';context='Siklus '+data.year+' · Sebelum disimpan'}else if(page==='detail'){title='Ringkasan rencana';description='Tinjau prioritas perbaikan, kegiatan, anggaran, dan capaian rencana sekolah.';context='Siklus '+data.year}else if(page==='self-evaluation'){title='Evaluasi Diri';description=reflectionYear?'Refleksikan cara sekolah menjalani setiap tahap untuk memperbaiki siklus berikutnya.':'Refleksikan siklus yang sudah selesai. Mulai penilaian, lanjutkan draf, atau lihat hasil refleksi sebelumnya.';context=reflectionYear?'Siklus '+reflectionYear:'Belajar dari perjalanan sekolah'}else if(page==='downloads'){title='Unduh';description='Unduh Rapor Pendidikan dan dapatkan rekomendasi Perencanaan Berbasis Data satuan pendidikan Anda.';context=''}else if(page==='rapor-root'){title=ind(reportIndicator).name;description='Pelajari akar masalah dan inspirasi perbaikan berdasarkan capaian indikator sekolah.'}else if(page==='diagnosis-alternatives'){context='Alternatif desain · Diagnosis lama'}else if(!['rapor','home','flow','review','detail','self-evaluation','rapor-root','diagnosis-alternatives'].includes(page)){title='Pusat Bantuan';description='Panduan singkat menyusun dan menjalankan siklus perbaikan sekolah.';context='Panduan penggunaan'}return `<section class="page-title-banner ${page==='downloads'?'download-title-banner':''}" aria-label="Judul halaman"><div class="page-title-inner">${context?`<p class="page-title-context">${esc(context)}</p>`:''}<h1>${esc(title)}</h1><p class="page-title-description">${esc(description)}</p></div></section>`}

function render(){ $('#app').innerHTML=`${mainNavbar()}${pageTitleBanner()}<main class="wrap page-${page} ${page==='self-evaluation'&&reflectionYear&&reflectionStep<6?'reflection-compact-page':''}">${page==='menetapkan-cards'?menetapkanAlternative():page==='menetapkan-alternative'?legacyMenetapkan():page==='downloads'?downloadsPage():page==='home'?home():page==='flow'?flow():page==='review'?review():page==='detail'?detail():page==='diagnosis-alternatives'?legacyRapor():page==='rapor'?rapor():page==='rapor-root'?raporRoot():page==='self-evaluation'?selfEvaluation():help()}</main><footer>Prototipe lokal · Data sekolah dan data capaian merupakan simulasi</footer><button class="demo-fab" onclick="toggleDemo()">◈ &nbsp; Menu demo ${demo?'×':'⌃'}</button>${demo?demoPanel():''}${priorityTargetDialog()}`;}
function go(p){page=p;if(p==='self-evaluation')reflectionYear='';render();window.scrollTo(0,0)}
function home(){if(data.status==='Draf'&&!data.priorities.length&&!data.activities.length&&!history.length)return `${sixMIntroduction('start()')}<section class="card empty cycle-empty-state"><h2>Belum ada siklus</h2><p class="muted">Mulai siklus pertama untuk menetapkan prioritas dan menyusun rencana perbaikan sekolah.</p></section>`;const active=data.status==='Sudah ada rencana'&&listRktStatus(data)==='Sudah ada rencana';return `<div class="row"><div><div class="eyebrow">SMA Rakyat 3 · NPSN 20260001</div><h1>Siklus 6M</h1></div><span class="tag">Tahun ajaran ${data.year}</span></div>${dashboardBanner()}${active?`<div class="grid dashboard-metrics"><div class="card"><div class="muted">Prioritas perbaikan</div><div class="metric">${data.priorities.length}<span class="sub"> / 3 indikator</span></div><small>Fokus pada perubahan yang paling dibutuhkan.</small></div><div class="card"><div class="muted">Kegiatan direncanakan</div><div class="metric">${data.activities.length}<span class="sub"> kegiatan</span></div><small>Setiap kegiatan terhubung dengan prioritas.</small></div><div class="card"><div class="muted">Kemajuan pelaksanaan</div><div class="metric">${Math.round(data.activities.reduce((sum,a)=>sum+activityPercent(a),0)/Math.max(1,data.activities.length))}<span class="sub">%</span></div><small>Terus catat perubahan di sekolah.</small></div></div>`:''}<div class="row section"><div><h2>Siklus Sekolah</h2><p class="muted">Satu perjalanan perbaikan untuk setiap tahun ajaran.</p></div></div><div class="card rkt-table-card"><div class="table-scroll"><table class="rkt-list"><thead><tr><th>Tahun ajaran</th><th>Prioritas & kegiatan</th><th>Status</th><th class="rkt-action-heading">Tindakan</th><th><span class="sr-only">Menu lainnya</span></th></tr></thead><tbody>${data.priorities.length||data.status!=='Draf'?dashboardRow(data,'current',0):''}${history.map((h,i)=>dashboardRow(h,'history',i)).join('')}</tbody></table></div></div><div class="notice">ⓘ &nbsp; Siklus 6M disusun untuk satu tahun ajaran, mulai Juli hingga Juni. Rencana yang telah disimpan tetap menjadi acuan saat Anda memperbarui pelaksanaan dan capaian.</div>`}
function sixMIcon(index){const files=['img-expectation-score-arrow-target','img-magnifying-glass-identify','img-document-pencil-fill','img-task-checklist','img-presentation-data-chart','img-circulation-progress-chart-data-document'];return `<img class="sixm-illustration" src="assets/illustrations/${files[index]}.svg" width="60" height="60" alt="" aria-hidden="true">`}
function sixMIntroduction(action){const steps=[['Menetapkan','Pilih prioritas<br>perbaikan sekolah','◎'],['Memetakan','Kenali akar<br>masalahnya','⌕'],['Merencanakan','Susun kegiatan<br>dan anggaran','▤'],['Melaksanakan','Jalankan kegiatan<br>yang direncanakan','▷'],['Mengevaluasi','Nilai efektivitas<br>kegiatan sekolah','✓'],['Mengendalikan','Tentukan perbaikan<br>dan tindak lanjut*','↻']];return `<section class="hero dashboard-banner sixm-intro-banner"><h2>Kenali langkah perbaikan sekolah</h2><p class="sixm-intro-copy">Enam langkah untuk mengubah data menjadi perbaikan yang berangkat dari kebutuhan murid, selama satu tahun ajaran.</p><ol class="sixm-journey">${steps.map(([name,description,icon],j)=>`<li><div class="sixm-circle">${sixMIcon(j)}<b>${j+1}</b></div><h3>${name}</h3><p>${description}</p></li>`).join('')}</ol><p class="sixm-loop">* Hasil evaluasi menjadi bekal siklus berikutnya.</p><div class="sixm-banner-footer"><p>Mulai dengan memilih 2–3 prioritas yang paling dibutuhkan murid.</p><div class="sixm-intro-actions"><button class="sixm-learn-more" onclick="go('help')">Pelajari Selengkapnya</button><button class="banner-action" onclick="${action}">Mulai siklus tahun ajaran ${esc(data.status==='Selesai'?(Number(data.year.split('/')[0])+1)+'/'+(Number(data.year.split('/')[1])+1):data.year)} →</button></div></div></section>`}
function dashboardBanner(){let title,description,action,label,mode='';if(data.status==='Sudah ada rencana'&&data.evaluationSubmitted){mode='followup';title='Jadikan hasil evaluasi sebagai langkah berikutnya';description='Tentukan kegiatan yang perlu diperbaiki, dipertahankan, atau dilanjutkan pada tahun ajaran berikutnya.';label='Lanjutkan tindak lanjut';action='openFollowup()'}else if(data.status==='Sudah ada rencana'&&data.evaluationOpen){mode='evaluation';title='Saatnya meninjau dampak kegiatan sekolah';description=`Periode evaluasi dibuka: ${evaluationWindow()}. Gunakan bukti pelaksanaan untuk menilai efektivitas kegiatan, bukan hanya jumlah kegiatan yang selesai. Bandingkan target dan capaian untuk menentukan langkah perbaikan berikutnya.`;label='Lakukan evaluasi';action='openEvaluation()'}else if(data.status==='Sudah ada rencana'){title='Terus dampingi kemajuan sekolah';description='Catat capaian dan bukti kegiatan yang sudah berjalan. Setiap pembelajaran menjadi bekal untuk perbaikan berikutnya.';label='Masukkan capaian';action='openExecution()'}else if(data.status==='Draf'&&data.priorities.length){title='Lanjutkan rencana perbaikan sekolah';description='Draf Anda sudah tersimpan. Lengkapi prioritas dan kegiatan untuk memulai perubahan yang berarti bagi murid.';label='Lanjutkan penyusunan';action='start()'}else if(!['Draf','Selesai'].includes(data.status)){title='Rencana sekolah siap dijalankan';description='Tinjau ringkasan rencana dan catat capaian pelaksanaannya.';label='Lihat ringkasan rencana';action="go('detail')"}else{title='Mulai rencana baru untuk kemajuan sekolah';description='Pilih 2–3 prioritas yang paling dibutuhkan murid dan rancang kegiatan perbaikannya untuk satu tahun ajaran.';label='Mulai Siklus';action=data.status==='Selesai'?'newCycle()':'start()'}if(label==='Mulai Siklus')return sixMIntroduction(action);return `<div class="hero dashboard-banner ${mode}"><div><div class="eyebrow">${mode==='evaluation'?'Periode evaluasi telah dibuka':mode==='followup'?'Evaluasi selesai · tindak lanjut':'Perbaikan dimulai dari kebutuhan murid'}</div><h2>${title}</h2><p>${description}</p><button class="banner-action" onclick="${action}">${label} →</button></div><div class="hero-art" aria-hidden="true">${mode==='evaluation'?'◎':mode==='followup'?'↗':'▥'}</div></div>`}
function dashboardRow(rkt,kind,index){const current=kind==='current';const status=current&&rkt.status==='Sudah ada rencana'?(rkt.evaluationSubmitted?'Tindak lanjut belum selesai':rkt.evaluationOpen?'Masa evaluasi':listRktStatus(rkt)):listRktStatus(rkt);let primary='',menu=[];const view=`showRktRecord('${kind}',${index})`;menu.push(['Lihat Siklus',view]);if(!current||rkt.status==='Selesai'){primary=`<button onclick="showOutcome('${kind}',${index},'summary')">Lihat ringkasan hasil</button>`;menu.push(['Lihat hasil evaluasi',`showOutcome('${kind}',${index},'evaluation')`],['Lihat tindak lanjut',`showOutcome('${kind}',${index},'followup')`])}else if(rkt.status==='Draf'){primary='<button class="primary" onclick="start()">Lanjutkan penyusunan</button>';menu.push(['Hapus draf','deleteCurrentDraft()'])}else if(rkt.status==='Sudah ada rencana'){if(listRktStatus(rkt)==='Sudah ada rencana')menu.push(['Ubah rencana','editCurrentPlan()']);if(rkt.evaluationSubmitted){primary='<button class="primary" onclick="openFollowup()">Lanjutkan tindak lanjut</button>';menu.push(['Lihat hasil evaluasi',`showOutcome('current',0,'evaluation')`])}else{primary=`<button class="${rkt.evaluationOpen?'':'primary'}" onclick="openExecution()">Masukkan capaian</button>${rkt.evaluationOpen?'<button class="primary" onclick="openEvaluation()">Lakukan evaluasi</button>':''}`}}else primary=`<button onclick="go('detail')">Lihat ringkasan rencana</button>`;let row=`<tr><td><b>Siklus ${esc(rkt.year)}</b><small>Juli ${esc(rkt.year.split('/')[0])} – Juni ${esc(rkt.year.split('/')[1])}</small></td><td>${rkt.priorities.length} prioritas · ${rkt.activities.length} kegiatan</td><td>${badge(status)}</td><td class="rkt-action-cell"><div class="rkt-row-actions">${primary}</div></td><td class="rkt-menu-cell"><details class="row-overflow" ontoggle="positionRowMenu(this)"><summary aria-label="Pilihan lain Siklus ${esc(rkt.year)}" title="Pilihan lain">⋮</summary><div class="row-overflow-menu">${menu.map(([text,handler])=>`<button class="${text==='Hapus draf'?'danger':''}" onclick="${handler}">${text}</button>`).join('')}</div></details></td></tr>`;return row}
function positionRowMenu(el){if(!el.open)return;document.querySelectorAll('.row-overflow').forEach(other=>{if(other!==el)other.open=false});const rect=el.querySelector('summary').getBoundingClientRect();const menu=el.querySelector('.row-overflow-menu');menu.style.right=Math.max(16,window.innerWidth-rect.right)+'px';const height=menu.getBoundingClientRect().height;if(rect.bottom+height+12>window.innerHeight){menu.style.top='auto';menu.style.bottom=(window.innerHeight-rect.top+6)+'px'}else{menu.style.bottom='auto';menu.style.top=(rect.bottom+6)+'px'}}
function sampleArchive(){const s=seed();s.year='2026/2027';s.status='Selesai';s.budget='Disetujui';s.priorities=['lit','num'];s.targets={lit:35,num:50};s.roots={lit:[ind('lit').roots[0]],num:[ind('num').roots[0]]};s.activities=s.priorities.map((id,j)=>({id:'old-'+id,indicator:id,name:j?'Pembelajaran numerasi berbasis masalah sehari-hari':'Pendampingan pembelajaran literasi',root:s.roots[id][0],implementation:j?'Guru mencoba masalah sehari-hari dalam pembelajaran numerasi dan merefleksikan hasilnya bersama.':'Dua guru inti mendampingi praktik membaca teks informasi melalui komunitas belajar.',needsBudget:j===0,budget:j===0?2500000:0,budgetLines:j===0?[{description:'Bahan pendampingan dan bacaan',month:'Agu',quantity:25,unit:'paket',price:100000}]:[],months:[]}));s.evaluationOpen=true;s.evaluationSubmitted=true;s.activities.forEach(a=>{s.progress[a.id]={notes:'Kegiatan terlaksana dan dibahas dalam refleksi bersama guru.',link:'',files:[]};s.evaluation[a.id]={result:'Efektif',notes:'Guru menerapkan praktik pembelajaran yang disepakati.'};s.follow[a.id]={type:'Pemeliharaan',action:'Pertahankan pendampingan dan bagikan praktik baik.',carry:true}});return s}
function recordFor(kind,index){return kind==='current'?data:kind==='history'?history[index]:sampleArchive()}
function showRktRecord(kind,index){const current=data;data=recordFor(kind,index);page='detail';$('#app').innerHTML='';render();$('.wrap').innerHTML=approvedRktView();data=current;window.scrollTo(0,0)}
function showOutcome(kind,index,view){const current=data;const r=recordFor(kind,index);const title=view==='evaluation'?'Hasil evaluasi':view==='followup'?'Tindak lanjut':'Ringkasan hasil';page='detail';render();$('.wrap').innerHTML=`<button class="quiet" onclick="go('home')">← Kembali ke daftar RKT</button><div class="eyebrow">RKT ${esc(r.year)}</div><h1>${title}</h1><p class="muted">Catatan hasil dan pembelajaran siklus perbaikan sekolah.</p>${r.activities.map(a=>`<div class="card"><span class="tag">${esc(ind(a.indicator).name)}</span><h2 style="margin-top:12px">${esc(a.name)}</h2>${view!=='followup'?`<p>Target: <b>${esc(a.quantity)} ${esc(a.unit)}</b> · Capaian: <b>${esc(r.progress[a.id]?.achieved??0)} ${esc(a.unit)}</b></p>${badge(r.evaluation[a.id]?.result||'Belum dievaluasi')}<p class="section">${esc(r.evaluation[a.id]?.notes||'Belum ada catatan evaluasi.')}</p>`:''}${view!=='evaluation'?`<div class="line"></div><h3>Tindak lanjut</h3><p>${esc(r.follow[a.id]?.action||'Belum ada tindak lanjut.')}</p>${r.follow[a.id]?.carry?'<span class="badge blue">Dibawa ke RKT berikutnya</span>':''}`:''}</div>`).join('')}`;data=current;window.scrollTo(0,0)}
function reviseCurrent(){if(data.status!=='Perlu revisi')return;stage=data.revisionKind==='budget'?2:0;go('flow');if(stage===2&&data.activities.length){const a=data.activities[0];data.planSaved={...data.planSaved,[a.indicator]:false};plannerOpen[a.indicator]=1;save();render();document.getElementById(a.id+'-budget')?.focus()}}
function deleteCurrentDraft(){if(data.status!=='Draf')return;if(!confirm('Hapus draf RKT ini beserta seluruh isian dan lampirannya?'))return;const year=data.year;data=seed();data.year=year;save();go('home');toast('Draf dihapus.')}
function evaluationWindow(){return '1–30 Juni '+data.year.split('/')[1]+' (simulasi)'}
function openEvaluation(){if(data.status!=='Sudah ada rencana'||!data.evaluationOpen)return toast('Periode evaluasi belum dibuka.');stage=4;go('flow')}
function openFollowup(){if(data.status!=='Sudah ada rencana'||!data.evaluationSubmitted)return toast('Selesaikan evaluasi terlebih dahulu.');stage=5;go('flow')}
function start(){stage=0;go('flow')}function openCurrent(){if(['Draf','Perlu revisi'].includes(data.status))start();else go('detail')}
function goToPreviousStep(index){if(!Number.isInteger(index)||index<0||index>=stage)return;save();stage=index;if(['menetapkan-alternative','menetapkan-cards'].includes(page))page='flow';render();window.scrollTo(0,0)}
function steps(){return `<nav class="steps" aria-label="Tahap Siklus 6M">${names.map((n,i)=>i<stage?`<button type="button" class="step done" onclick="goToPreviousStep(${i})" aria-label="Kembali ke tahap ${n}"><span class="num">✓</span>${n}</button>`:`<div class="step ${i===stage?'on':''}" ${i===stage?'aria-current="step"':''}><span class="num">${i+1}</span>${n}</div>`).join('')}</nav>`}
const headings=['Tetapkan prioritas sekolah','Kenali penyebab, temukan arah perbaikan','Ubah prioritas menjadi langkah nyata','Catat langkah yang sudah berjalan','Pelajari dampak kegiatan sekolah','Jadikan pembelajaran sebagai langkah berikutnya'];
const descriptions=['Pilih 2–3 indikator sesuai kebutuhan murid dan tetapkan target capaiannya.','Setiap sekolah memiliki konteks berbeda. Telaah saran akar masalah dan pilih yang sesuai dengan kondisi nyata sekolah.','Rancang kegiatan yang jelas, terukur, dapat dijalankan, dan menjawab akar masalah yang dipilih.','Setiap kemajuan berarti. Catat pelaksanaan, kendala, dan bukti dari kegiatan sehari-hari.','Tinjau implementasi, catatan, dan bukti pelaksanaan untuk menilai efektivitas kegiatan. Refleksi yang jujur membantu sekolah menentukan perbaikan selanjutnya.','Tentukan apa yang perlu diperbaiki, dipertahankan, atau dilanjutkan agar perubahan terus tumbuh.'];
function flow(){if(stage===0&&['Draf','Perlu revisi'].includes(data.status))return menetapkanTablePage();if(stage===4&&(!data.evaluationOpen||data.status!=='Sudah ada rencana'))return `<button class="quiet" onclick="go('home')">← Kembali ke daftar RKT</button><div class="card empty"><h1>Evaluasi belum dibuka</h1><p class="muted">Evaluasi tersedia untuk RKT aktif selama periode yang ditentukan admin.</p><button onclick="openExecution()">Masukkan capaian</button></div>`;let locked=stage<3&&!['Draf','Perlu revisi'].includes(data.status)&&!(stage===2&&listRktStatus(data)==='Sudah ada rencana');return `<button class="quiet" onclick="go('home')">← Kembali ke daftar RKT</button><div class="flow-heading"><div><div class="eyebrow">RKT ${data.year} · ${period()}</div><h1>${headings[stage]}</h1><p class="muted">${descriptions[stage]}</p></div><div class="document-status">${badge(data.status)}<span class="save" role="status">✓ ${stage<3?"Draf":"Perubahan"} tersimpan otomatis</span></div></div>${steps()}${locked?'<div class="notice">Rencana telah disimpan. Anda dapat meninjau isinya melalui ringkasan rencana.</div><button onclick="go(\'detail\')">Lihat ringkasan RKT</button>':stage>=3&&data.status!=='Sudah ada rencana'?'<div class="card empty"><h2>RKT belum aktif</h2><p class="muted">Pelaksanaan dapat dicatat setelah rencana prioritas disimpan.</p><button onclick="go(\'detail\')">Lihat ringkasan rencana</button></div>':`${stage===0?`<div class="priority-layout"><section class="flow-content">${priorities()}</section>${chosenPanel()}</div>`:`<section class="flow-content">${[priorities,roots,planning,execution,evaluation,control][stage]()}</section>`}${actions()}`}`}
function actions(){if(stage===2)return `<div class="actions planning-page-actions"><button onclick="back()">← Sebelumnya</button><button class="primary" onclick="next()">Simpan rencana prioritas</button></div>`;if(stage===4||stage===5)return `<div class="actions"><button onclick="save();go('home')">Simpan & kembali ke daftar</button><button class="primary" onclick="next()">${stage===4?'Simpan evaluasi & lanjutkan':'Selesaikan siklus'} →</button></div>`;if(stage===3)return `<div class="actions"><button onclick="go('home')">← Kembali ke daftar RKT</button><button class="primary" onclick="save();go('home');toast('Capaian berhasil disimpan.')">Simpan capaian</button></div>`;if(stage===0)return '';return `<div class="actions"><button onclick="back()">← ${stage===0?'Kembali ke daftar':'Sebelumnya'}</button><div><button onclick="save();go('home')">Simpan & keluar</button><button class="primary" onclick="next()">${stage===2?'Tinjau rencana':stage===5?'Selesaikan siklus':'Lanjutkan'} →</button></div></div>`}
const openDimensions=new Set();
const dimensionNames=['Mutu Manajemen','Mutu Pendidikan dan Tenaga Kependidikan','Mutu Pembelajaran','Mutu Lulusan'];
const dimensionOf=i=>i.desc.split(' · SNP:')[0].replace('Mutu Pendidik & Tenaga Kependidikan','Mutu Pendidikan dan Tenaga Kependidikan');
function subindicatorRow(c){return `<div class="subindicator-row"><div><span class="source-text">${esc(c.code)}</span><span>${esc(c.name)}</span></div><b>${scoreText(c)}${c.unit?' '+esc(c.unit):''}</b></div>`}
function indicatorSubindicators(i){if(!i.children.length)return '<p class="source-text">Tidak ada subindikator dalam referensi.</p>';return i.children.slice(0,2).map(subindicatorRow).join('')+(i.children.length>2?`<div class="subindicator-extra" hidden>${i.children.slice(2).map(subindicatorRow).join('')}</div><a href="#" role="button" class="subindicator-toggle" aria-expanded="false" aria-label="Lihat semua subindikator ${esc(i.name)}" onclick="event.preventDefault();toggleSubindicators(this)">Lihat semua (${i.children.length}) ↓</a>`:'')}
function toggleSubindicators(button){const expanded=button.getAttribute('aria-expanded')==='true';button.previousElementSibling.hidden=expanded;button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'Lihat semua ('+button.closest('.indicator-children').querySelectorAll('.subindicator-row').length+') ↓':'Tampilkan lebih sedikit ↑';button.setAttribute('aria-label',(expanded?'Lihat semua':'Tampilkan lebih sedikit')+' subindikator '+button.closest('.indicator-card').querySelector('h3').textContent)}
function indicatorCard(i,topIds,readOnly=false){return `<article class="card indicator-card ${!readOnly&&data.priorities.includes(i.id)?'selected':''}"><div class="indicator-overview"><div class="indicator-choice"><span><span class="source-text">${esc(i.code)}</span><h3>${esc(i.name)}</h3></span></div><span class="tag">${esc(i.source)}</span>${topIds.has(i.id)?'<span class="badge lowest-tag">Indikator Prioritas</span>':''}<p class="sub">${esc(i.desc)}</p><p class="source-text">${esc(i.origin)} · ${esc(i.period)}</p></div><div class="indicator-score"><span class="sub">Capaian awal</span><div class="metric">${scoreText(i)}<span class="sub"> ${esc(i.unit)}</span></div><span class="badge ${i.color}">${esc(i.level)}</span>${typeof i.previous==='number'&&typeof i.score==='number'?`<p class="source-text score-change">${new Intl.NumberFormat('id-ID',{signDisplay:'always',maximumFractionDigits:2}).format(i.score-i.previous)} poin dari 2024</p>`:''}</div><div class="indicator-children"><b class="sub">Subindikator</b>${indicatorSubindicators(i)}</div>${readOnly?'':`<div class="indicator-target priority-button-cell"><button class="${data.priorities.includes(i.id)?'priority-selected':'primary'}" aria-label="${data.priorities.includes(i.id)?'Batalkan prioritas':'Jadikan prioritas'} ${esc(i.name)}" aria-pressed="${data.priorities.includes(i.id)}" onclick="choose('${i.id}',${!data.priorities.includes(i.id)})">${data.priorities.includes(i.id)?'✓ Dipilih · Batalkan':'Jadikan prioritas'}</button></div>`}</article>`}
function priorities(){
 const visible=indicators;
 const lowest=['A.1','D.8','A.2','D.4','D.1','A.3'].map(code=>visible.find(i=>i.source==='Rapor Pendidikan'&&i.code===code)).filter(Boolean);
 const topIds=new Set(lowest.map(i=>i.id));
 return `<section class="lowest-section" aria-labelledby="lowest-heading"><div class="section-intro"><span class="eyebrow">Titik awal refleksi</span><h2 id="lowest-heading">Indikator Prioritas</h2><p class="sub">Enam indikator berikut mengikuti Rekomendasi Prioritas pada tab 2.2 Rapor Pendidikan. Pilih 2–3 indikator yang paling sesuai dengan kebutuhan murid di sekolah Anda.</p></div><div class="indicator-list">${lowest.map(i=>indicatorCard(i,topIds)).join('')}</div></section>
 <section class="other-indicators" aria-labelledby="other-heading"><div class="section-intro"><h2 id="other-heading">Indikator lainnya</h2><p class="sub">Buka dimensi untuk melihat seluruh indikator berdasarkan urutan kode. Enam indikator prioritas di atas juga tetap ditampilkan di kelompoknya dengan penanda Indikator Prioritas.</p></div>
 ${dimensionNames.map((dim,index)=>{const group=visible.filter(i=>dimensionOf(i)===dim).sort(compareIndicatorAchievement);return `<details class="dimension-group" ${openDimensions.has(dim)?'open':''} ontoggle="if(this.open)openDimensions.add('${dim}');else openDimensions.delete('${dim}')"><summary><span><span class="dimension-number">0${index+1}</span><b>${dim}</b>${group.some(i=>topIds.has(i.id))?`<span class="dimension-priority-tag">${group.filter(i=>topIds.has(i.id)).length} indikator prioritas</span>`:''}</span><span class="dimension-meta">${group.length} indikator <span class="dimension-chevron">⌄</span></span></summary><div class="dimension-body"><div class="indicator-list">${group.map(i=>indicatorCard(i,topIds)).join('')||'<p class="muted">Tidak ada indikator dari sumber ini.</p>'}</div></div></details>`}).join('')}</section><div class="notice">Pilih 2–3 indikator dari sumber mana pun. Anda tidak perlu memilih dari ketiga sumber.</div>`;
}
function priorityTargetDialog(){return `<dialog id="priority-target-dialog" class="priority-target-dialog"><form onsubmit="event.preventDefault();savePriorityTarget()"><span class="tag">Menetapkan prioritas</span><h2 id="priority-target-title"></h2><p class="sub" id="priority-target-baseline"></p><input type="hidden" id="priority-target-id"><label for="priority-target-value">Target capaian akhir tahun ajaran</label><p class="sub" id="priority-target-help"></p><input required type="number" step="any" min="0" id="priority-target-value" aria-describedby="priority-target-help priority-target-error"><p id="priority-target-error" class="priority-target-error" role="alert"></p><div class="actions"><button type="button" onclick="document.getElementById('priority-target-dialog').close()">Batal</button><button class="primary" type="submit">Simpan target</button></div></form></dialog>`}
function requestPriorityTarget(id){if(!['Draf','Perlu revisi'].includes(data.status))return;const i=ind(id);if(!data.priorities.includes(id)&&data.priorities.length>=3)return toast('Maksimal 3 indikator prioritas.');const dialog=document.getElementById('priority-target-dialog');document.getElementById('priority-target-id').value=id;document.getElementById('priority-target-title').textContent=i.name;document.getElementById('priority-target-baseline').textContent='Capaian awal: '+scoreText(i)+' '+i.unit+' · Tahun ajaran '+data.year;document.getElementById('priority-target-help').textContent='Tetapkan target yang realistis dalam satuan '+(i.unit||'skor')+'.';const input=document.getElementById('priority-target-value');input.max=i.max;input.value=data.targets[id]??'';document.getElementById('priority-target-error').textContent='';dialog.showModal();input.focus()}
function savePriorityTarget(){const id=document.getElementById('priority-target-id').value,i=ind(id),raw=document.getElementById('priority-target-value').value,value=Number(raw);if(!['Draf','Perlu revisi'].includes(data.status))return;if(raw===''||!Number.isFinite(value)||value<0||value>i.max||(typeof i.score==='number'&&value<=i.score)){document.getElementById('priority-target-error').textContent='Isi target di atas capaian awal dan tidak melebihi '+i.max+' '+(i.unit||'skor')+'.';return}if(!data.priorities.includes(id)){if(data.priorities.length>=3)return;data.priorities.push(id)}data.targets[id]=value;document.getElementById('priority-target-dialog').close();save();render()}
function choose(id,on){if(on){requestPriorityTarget(id);return}if(on&&data.priorities.length===3){toast('Maksimal 3 indikator prioritas.');render();return}if(!on&&data.activities.some(a=>a.indicator===id)){toast('Hapus kegiatan terkait terlebih dahulu sebelum mengganti prioritas.');render();return}data.priorities=on?[...data.priorities,id]:data.priorities.filter(x=>x!==id);save();render()}
function indicatorTargetContext(id){const i=ind(id);return `<div class="indicator-target-context"><span>Capaian awal: <b>${scoreText(i)} ${esc(i.unit)}</b></span><span aria-hidden="true">→</span><span>Target ${esc(data.year)}: <b>${data.targets[id]!==undefined&&data.targets[id]!==''?scoreText({score:Number(data.targets[id])}):'Belum ditetapkan'} ${esc(i.unit||'skor')}</b></span></div>`}
function rootIndicatorInfo(i,key){return `<span class="source-text">${esc(i.code)}</span><div class="table-indicator-title"><h3>${esc(i.name)}</h3><button type="button" class="indicator-description-tooltip" aria-label="Deskripsi ${esc(i.name)}" aria-controls="indicator-description-root-${key}" aria-expanded="false" onclick="toggleIndicatorDescription(this,'root-${key}')">ⓘ</button><div popover="auto" class="indicator-description-popover" id="indicator-description-root-${key}" role="note">${esc(i.definition||i.desc||'Deskripsi belum tersedia.')}</div></div>`}
function rootAchievement(i){return `<div class="table-achievement">${i.level?`<span class="badge ${typeof i.score==='number'?esc(i.color||''):''}">${esc(i.level)}</span>`:''}<strong class="table-baseline">${typeof i.score==='number'?scoreText(i)+' '+esc(i.unit||''):'Tidak tersedia'}</strong></div>`}
function rootSubindicatorTable(id){const parent=ind(id),options=[...parent.roots,...(data.custom[id]||[])];if(!options.length)return '';return `<div class="table-scroll"><table class="menetapkan-indicator-table root-subindicator-table"><thead><tr><th scope="col">Subindikator / akar masalah</th><th scope="col">Capaian awal</th><th scope="col">Perubahan dari 2024</th><th scope="col">Pilih</th></tr></thead><tbody>${options.map((r,j)=>{const code=r.split(' · ')[0],found=j<parent.roots.length?indicators.flatMap(i=>[i,...(i.children||[])]).find(i=>i.code===code):null;return `<tr class="${(data.roots[id]||[]).includes(r)?'selected-indicator-row':''}"><td>${found?rootIndicatorInfo(found,id+'-'+j):esc(r)}</td><td>${found?rootAchievement(found):'<span class="table-no-comparison">Tidak tersedia</span>'}</td><td class="table-indicator-change">${found?reportDelta(found).replace('Capaian ','').replace('class="muted"','class="table-no-comparison"'):'<span class="table-no-comparison">Data pembanding belum tersedia</span>'}</td><td><input type="checkbox" aria-label="Pilih akar masalah ${esc(r)}" ${(data.roots[id]||[]).includes(r)?'checked':''} onchange="setRoot('${id}',${j},this.checked)"></td></tr>`}).join('')}</tbody></table></div>`}
function roots(){return data.priorities.map(id=>{const i=ind(id);return `<article class="card root-mapping-card" id="root-card-${id}"><div class="root-summary-header"><div class="root-summary-identity"><p class="source-text">${esc(i.code)} · ${esc(i.source)}</p><div class="root-summary-title"><h2>${esc(i.name)}</h2><button type="button" class="indicator-description-tooltip" aria-label="Deskripsi ${esc(i.name)}" aria-controls="indicator-description-root-${id}-main" aria-expanded="false" onclick="toggleIndicatorDescription(this,'root-${id}-main')">ⓘ</button><div popover="auto" class="indicator-description-popover" id="indicator-description-root-${id}-main" role="note">${esc(i.definition||i.desc||'Deskripsi belum tersedia.')}</div></div>${i.level?`<span class="badge ${typeof i.score==='number'?esc(i.color||''):''}">${esc(i.level)}</span>`:''}<p class="root-summary-change">${reportDelta(i).replace('Capaian ','')}</p></div><div class="root-summary-metrics"><div><span>Capaian awal · ${esc(i.period||'—')}</span><strong>${typeof i.score==='number'?scoreText(i)+' '+esc(i.unit||''):'Tidak tersedia'}</strong></div><div><span>Target · ${esc(data.year)}</span><strong>${data.targets[id]!==undefined&&data.targets[id]!==''?scoreText({score:Number(data.targets[id])})+' '+esc(i.unit||''):'Belum ditetapkan'}</strong></div></div></div><h3 class="root-mapping-question">Apa yang paling memengaruhi capaian indikator ini di sekolah Anda?</h3>${!i.roots.length?'<p class="notice">Rekomendasi akar masalah belum tersedia dalam spreadsheet untuk indikator ini. Tambahkan akar masalah berdasarkan hasil pengamatan atau diskusi sekolah.</p>':''}${rootSubindicatorTable(id)}<label for="custom-${id}">Akar masalah lain dari sekolah</label><div class="inline"><input id="custom-${id}" placeholder="Tuliskan hasil pengamatan atau diskusi sekolah"><button onclick="addRoot('${id}')">＋ Tambah</button></div><p class="source-text" style="margin-top:12px">${i.rootReference==='2.2'?'Dua rekomendasi akar masalah bersumber dari tab 2.2 Rekomendasi Prioritas Rapor Pendidikan.':i.rootReference==='2.1'?'Rekomendasi akar masalah bersumber dari tab 2.1 Rekomendasi Keseluruhan Rapor Pendidikan.':i.source==='Rapor Pendidikan'?'Tab 2.1 dan 2.2 belum memuat pasangan akar masalah untuk indikator ini.':'Daftar bersumber dari referensi indikator.'} Telaah sesuai kondisi sekolah, bukan kesimpulan otomatis. Gunakan asesmen kelas, observasi, atau hasil diskusi guru.</p></article>`}).join('')}
function setRoot(id,j,on){const r=[...ind(id).roots,...(data.custom[id]||[])][j];data.roots[id]=on?[...(data.roots[id]||[]),r]:(data.roots[id]||[]).filter(x=>x!==r);save()}
function addRoot(id){let v=$('#custom-'+id).value.trim();if(!v)return;data.custom[id]=[...(data.custom[id]||[]),v];data.roots[id]=[...(data.roots[id]||[]),v];save();render()}
const activityRecommendations={"A.1": {"A.1.1": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi dengan mempelajari tentang teks informasi sebagai bagian dari kemampuan literasi melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses dan standar PTK.", "Kepala satuan pendidikan dan pendidik merencanakan pembelajaran dan mengimplementasikan pengetahuan tentang teks informasi melalui intrakurikuler, kokurikuler, dan/atau ekstrakurikuler untuk meningkatkan minat baca serta memperbaiki proses pembelajaran literasi peserta didik. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar isi, standar proses, dan standar penilaian.", "Kepala satuan pendidikan mendorong perbaikan kemampuan teks informasi melalui program dan kebijakan di satuan pendidikan, baik yang membutuhkan anggaran dan yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pembiayaan dan standar pengelolaan.", "Kepala satuan pendidikan mendorong pemenuhan dan ketersediaan buku teks utama yang disusun oleh pemerintah (Kemendikdasmen) dan buku teks pendamping yang disusun masyarakat/penerbit dan telah mendapatkan SK kelayakan dari pemerintah (Kemendikdasmen) sebagai buku pelajaran yang wajib digunakan pada satuan pendidikan untuk meningkatkan kualitas pembelajaran berdasarkan kurikulum yang berlaku, serta buku nonteks baik yang disusun oleh pemerintah maupun masyarakat/penerbit sebagai bahan bacaan dalam mendukung literasi di satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar sarana dan prasarana."], "D.3.1": ["Kepala satuan pendidikan dan pendidik mengadakan workshop untuk menyelaraskan visi-misi satuan pendidikan melalui dokumen perencanaan dan penganggaran satuan pendidikan untuk mendukung kemampuan literasi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan", "Kepala satuan pendidikan mengembangkan panduan praktis kepada pendidik untuk menerjemahkan visi-misi satuan pendidikan ke dalam proses pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar proses", "Kepala satuan pendidikan mendorong terlaksannya refleksi dengan seluruh warga satuan pendidikan untuk mengevaluasi visi-misi yang sudah diimplementasikan dalam program kerja dan proses pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan, standar proses, dan standat penilaian."]}, "D.8": {"D.8.1": ["Kepala satuan pendidikan dan pendidik mempelajari konsep dan praktik terkait toleransi agama dan budaya sebagai bagian dari salah satu upaya peningkatan iklim kebinekaan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan standar proses.", "Kepala satuan pendidikan dan pendidik mengimplementasikan pengetahuan tentang toleransi agama dan budaya pada beragam aktivitas intrakurikuler, kokurikuler, dan/atau ekstrakurikuler di satuan pendidikan untuk memperbaiki proses pembelajaran peserta didik. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses, standar isi, dan standar pengelolaan.", "Kepala satuan pendidikan mendorong perbaikan penerapan toleransi agama dan budaya di satuan pendidikan melalui program, kebijakan baik itu yang membutuhkan anggaran maupun yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan."], "D.6.1": ["Kepala satuan pendidikan dan pendidik mempelajari tentang konsep, pemahaman, dan sikap warga sekolah terkait kesetaraan gender untuk mendorong iklim kebinekaan di satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan standar proses.", "Kepala satuan pendidikan dan pendidik mengintegrasikan pengetahuan tentang pemahaman dan sikap warga sekolah terkait kesetaraan gender untuk memperbaiki proses pembelajaran peserta didik. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses, standar isi, dan standar pengelolaan.", "Kepala satuan pendidikan mendorong perbaikan pemahaman dan sikap warga sekolah terkait kesetaraan gender di satuan pendidikan melalui program, kebijakan, dan penganggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan."]}, "A.2": {"A.2.1": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi dengan mempelajari tentang domain bilangan sebagai bagian dari kemampuan numerasi melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses dan standar PTK.", "Kepala satuan pendidikan dan pendidik merencanakan pembelajaran dan mengimplementasikan pengetahuan tentang domain bilangan melalui intrakurikuler, kokurikuler, dan/atau ekstrakurikuler untuk memperbaiki proses pembelajaran numerasi peserta didik. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar isi, standar proses, dan standar penilaian.", "Kepala satuan pendidikan mendorong perbaikan kemampuan domain bilangan melalui program dan kebijakan di satuan pendidikan, baik yang membutuhkan anggaran dan yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pembiayaan dan standar pengelolaan."], "A.1.1": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi dengan mempelajari tentang teks informasi yang berorientasi pada penguatan kemampuan numerasi melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses dan standar PTK.", "Kepala satuan pendidikan dan pendidik merencanakan pembelajaran dan mengimplementasikan pengetahuan tentang teks informasi melalui intrakurikuler, kokurikuler, dan/atau ekstrakurikuler untuk meningkatkan minat baca serta memperbaiki proses pembelajaran numerasi peserta didik. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar isi, standar proses, dan standar penilaian.", "Kepala satuan pendidikan mendorong perbaikan kemampuan memahami teks informasi melalui program dan kebijakan di satuan pendidikan, baik yang membutuhkan anggaran dan yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pembiayaan dan standar pengelolaan."]}, "D.4": {"D.4.8": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi yang bertujuan untuk mengenali jenis-jenis kekerasan seksual yang mungkin terjadi di satuan pendidikan agar dapat mencegah dan menanggulangi segala bentuk perundungan/bullying di satuan pendidikan melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri dengan memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi untuk membangun lingkungan satuan pendidikan yang aman. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan standar proses", "Kepala satuan pendidikan dan pendidik merencanakan pembelajaran yang mendorong pencegahan dan penanggulanan segala bentuk kekerasan seksual bagi warga di satuan pendidikan lalu mengimplementasikannya dalam aktivitas intrakurikuler, kokurikuler, dan ekstrakurikuler. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan, standar proses, dan standar isi.", "Kepala satuan pendidikan mendukung ketersediaan dan penerapan program serta kebijakan untuk mencegah dan menanggulangi segala bentuk kekerasan seksual di satuan pendidikan melalui implementasi kegiatan, program, maupun pembuatan kebijakan, baik yang membutuhkan anggaran maupun yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan"], "D.8.1": ["Kepala satuan pendidikan dan seluruh warga sekolah meningkatkan kompetensi terkait toleransi antar agama dan budaya melalui pelatihan dan refleksi untuk mendukung terciptanya iklim keamanan satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK, standar pengelolaan, standar proses", "Kepala satuan pendidikan dan pendidik merancang dan melaksanakan program intrakurikuler dan/atau kokurikuler, dan/atau ekstrakurikuler yang memilki nilai-nilai toleransi antar agama dan budaya untuk meningkatkan iklim keamanan satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan, standar isi, dan standar proses", "Kepala satuan pendidikan menyusun kebijakan yang mendukung penerapan nilai-nilai toleransi antar agama dan budaya melalui program yang membutuhkan anggaran maupun tanpa anggaran untuk meningkatkan iklim keamanan satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan"]}, "D.1": {"D.1.2": ["Kepala satuan pendidikan dan pendidik memperbaiki kualitas pembelajaran melalui peningkatan kualitas kompetensi dalam memberikan dukungan afektif melalui pelatihan dan refleksi, untuk menciptakan interaksi yang konstruktif untuk mendukung suasana kondusif. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan standar proses.", "Kepala satuan pendidikan dan pendidik merancang dan mengimplementasikan strategi peningkatan kualitas pembelajaran yang mengintegrasikan dukungan perhatian, kepedulian, dan umpan balik pada kegiatan intrakurikuler, kokurikuler, dan/atau ekstrakurikuler. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses, standar isi, dan standar pengelolaan.", "Kepala satuan pendidikan menyusun kebijakan yang mendorong pendidik memberikan dukungan afektif kepada peserta didik melalui program yang membutuhkan anggaran maupun tanpa anggaran, untuk mendukung peningkatan kualitas pembelajaran yang terlihat dari meningkatnya kualitas interaksi antara pendidik, peserta didik, dan materi pembelajaran dalam proses pengajaran dan pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan."], "D.3.1": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi dalam mengintegrasikan visi-misi sekolah ke dalam proses pembelajaran melalui pelatihan dan refleksi untuk mendukung peningkatan kualitas pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan  standar proses.", "Kepala satuan pendidikan dan pendidik merancang dan melaksanakan proses pembelajaran yang selaras dengan visi-misi sekolah untuk memastikan peningkatan kualitas pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses, standar isi, dan standar pengelolaan", "Kepala satuan pendidikan menyusun kebijakan yang mendukung penerapan visi-misi sekolah dalam proses pembelajaran melalui program yang membutuhkan anggaran maupun tanpa anggaran untuk meningkatkan kualitas pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar  standar pengelolaan dan standar pembiayaan."]}, "A.3": {"A.3.5": ["Kepala satuan pendidikan dan pendidik meningkatkan kompetensi dengan mempelajari tentang pendidikan karakter yang berkaitan dengan menumbuhkan ketertarikan peserta didik dan kepedulian terhadap isu-isu global, kesetaraan gender, perbedaan agama dan budaya melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses dan standar PTK", "Kepala satuan pendidikan dan pendidik merencanakan dan mengimplementasikan pembelajaran yang mengintegrasikan isu-isu global, kesetaraan gender, perbedaan agama dan budaya melalui intrakurikuler, kokurikuler, dan/atau ekstrakurikuler untuk mendukung pengembangan pendidikan karakter. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan, standar isi, dan standar proses", "Kepala satuan pendidikan mendorong perbaikan dimensi Kebinekaan Global melalui program dan kebijakan di satuan pendidikan, baik yang membutuhkan anggaran dan yang tidak membutuhkan anggaran untuk mendukung pengembangan pendidikan karakter. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan dan standar pembiayaan"], "D.3.1": ["Kepala satuan pendidikan dan pendidik meningkatkan kemampuan dalam merumuskan, menyampaikan dan menerapkan visi-misi sekolah yang berorientasi pada pendidikan karakter melalui pelatihan, diskusi pada komunitas belajar, belajar mandiri dengan memanfaatkan berbagai sumber belajar, dan kegiatan lain yang menunjang peningkatan kompetensi. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar PTK dan standar pengelolaan", "Kepala satuan pendidikan dan pendidik mengintegrasikan pengetahuan tentang perumusan, penyampaian dan penerapan visi-misi sekolah dan mengimplementasikannya dalam berbagai aktivitas untuk mendukung pendidikan karakter. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan, standar proses dan standar isi.", "Kepala satuan pendidikan mendorong perbaikan perumusan visi-misi sekolah yang berorientasi pada pendidikan karakter melalui implementasi kegiatan, program, maupun pembuatan kebijakan, baik yang membutuhkan anggaran maupun yang tidak membutuhkan anggaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar pengelolaan"]}};
const plannerOpen={};
function plannerTargetValid(id){const v=Number(data.targets[id]);return data.targets[id]!==undefined&&data.targets[id]!==''&&Number.isFinite(v)&&v>=0&&v<=ind(id).max&&(typeof ind(id).score!=='number'||v>ind(id).score)}
function activityBasicsValid(a){return !!(a.name.trim()&&a.root&&(data.roots[a.indicator]||[]).includes(a.root)&&(a.implementation||'').trim())}

function activitySuccessValid(a){return a.target.trim()&&Number(a.quantity)>0&&a.unit.trim()&&a.proof.trim()}
function planningTargetPanel(id){const i=ind(id),target=data.targets[id],hasTarget=target!==undefined&&target!=='';return `<div class="planning-target-panel"><div><span>Capaian awal · ${esc(i.period||'—')}</span><strong>${scoreText(i)} ${esc(i.unit||'')}</strong></div><div><span>Target · ${esc(data.year)}</span><strong>${hasTarget?`${scoreText({score:Number(target)})} ${esc(i.unit||'skor')}`:'Belum ditetapkan'}</strong></div></div>`}
function planning(){return `<p class="muted planning-intro">Pilih kegiatan berdasarkan akar masalah sekolah, lalu jelaskan pelaksanaannya dan tentukan kebutuhan anggaran.</p>`+data.priorities.map(id=>{const acts=data.activities.filter(a=>a.indicator===id);return `<article class="card guided-plan" id="plan-${id}"><header class="guided-header planning-priority-header"><div class="planning-priority-name"><span class="tag">Prioritas perbaikan</span><h2>${esc(ind(id).name)}</h2></div>${planningTargetPanel(id)}</header><div class="guided-body">${recommendedActivities(id)}${acts.filter(a=>!a.recommendationKey).map(activityForm).join('')}<button onclick="addActivity('${id}')">＋ Tambah kegiatan sendiri</button></div></article>`}).join('')}

function rememberPlanner(el){if(!el.isConnected)return;if(el.open){plannerOpen[el.dataset.plan]=Number(el.dataset.step);document.querySelectorAll('.guided-step').forEach(other=>{if(other!==el&&other.dataset.plan===el.dataset.plan)other.open=false})}}
function advancePlanner(id,step){if(!plannerTargetValid(id)){toast('Tetapkan target yang valid di atas capaian awal sesuai skala indikator.');plannerOpen[id]=0;render();return}const acts=data.activities.filter(a=>a.indicator===id);if(step===2&&(!acts.length||acts.some(a=>!activityBasicsValid(a)))){toast('Lengkapi penjelasan implementasi kegiatan. Seluruh rincian anggaran bersifat opsional.');return}plannerOpen[id]=step;render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function recommendationShortDescription(code,index){const topics={'A.1.1':'membaca teks informasi','A.2.1':'domain bilangan','D.8.1':'toleransi agama dan budaya','D.6.1':'kesetaraan gender','D.4.8':'pencegahan dan penanganan kekerasan seksual','D.1.2':'dukungan psikologis','A.3.5':'kebinekaan global'};if(code==='D.3.1')return ['Selaraskan visi-misi sekolah dengan kebutuhan murid, perencanaan, dan penganggaran.','Bantu guru menerjemahkan visi-misi sekolah menjadi praktik pembelajaran.','Refleksikan penerapan visi-misi bersama warga sekolah untuk menentukan perbaikan.'][index]||'';const topic=topics[code]||'prioritas sekolah';if(index===0)return 'Perkuat pemahaman tentang '+topic+' melalui pelatihan, komunitas belajar, atau belajar mandiri.';if(index===1)return 'Terapkan '+topic+' dalam kegiatan intrakurikuler, kokurikuler, atau ekstrakurikuler.';if(index===2)return 'Siapkan program dan kebijakan sekolah yang mendukung '+topic+'.';if(index===3)return 'Penuhi kebutuhan buku teks dan nonteks untuk mendukung pembelajaran dan literasi.';return ''}
function recommendedActivities(id){const byRoot=activityRecommendations[ind(id).code]||{};const selected=data.roots[id]||[];const groups=selected.map(root=>({root,code:root.split(' · ')[0],list:byRoot[root.split(' · ')[0]]||[]})).filter(g=>g.list.length);return `<section class="activity-recommendations"><h3>Kegiatan Rekomendasi</h3><p class="sub">Kegiatan ini sesuai dengan akar masalah yang Anda pilih. Pilih kegiatan, lalu lengkapi rencana pelaksanaannya.</p>${groups.length?groups.map(g=>`<div class="recommendation-root"><h4>${esc(g.root)}</h4>${g.list.map((text,index)=>{const key=ind(id).code+':'+g.code+':'+index;const chosenActivity=data.activities.find(a=>a.indicator===id&&a.recommendationKey===key);const chosen=!!chosenActivity;return `<div class="recommendation-item ${chosen?'is-chosen':''}"><h3 class="recommendation-title">${esc(activitySummaryTitle({name:text,recommendationKey:key}))}</h3><p class="recommendation-description">${esc(text)}</p><button type="button" aria-pressed="${chosen}" onclick="${chosen?`removeActivity('${chosenActivity.id}')`:`selectRecommendedActivity('${id}','${g.code}',${index})`}">${chosen?'Batalkan pilihan':'Pilih kegiatan ini'}</button>${chosen?activityForm(chosenActivity,true):''}</div>`}).join('')}</div>`).join(''):'<p class="notice">Belum ada rekomendasi kegiatan dari tab 2.2 untuk akar masalah pilihan Anda. Anda tetap dapat menambahkan kegiatan sendiri.</p>'}</section>`}
function selectRecommendedActivity(id,code,index){const text=activityRecommendations[ind(id).code]?.[code]?.[index];const root=(data.roots[id]||[]).find(r=>r.split(' · ')[0]===code);if(!text||!root)return;const key=ind(id).code+':'+code+':'+index;if(data.activities.some(a=>a.indicator===id&&a.recommendationKey===key))return;const blank=data.activities.find(a=>a.indicator===id&&!a.name.trim()&&!a.target.trim()&&!a.realistic.trim()&&!a.relevant.trim()&&!a.months.length&&!Number(a.budget)&&!a.proof.trim()&&!a.quantity);const activity=blank||{id:'a'+Date.now(),indicator:id,target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],budget:0};Object.assign(activity,{name:text,root,recommendationKey:key});if(!blank)data.activities.push(activity);plannerOpen[id]=1;data.planSaved={...data.planSaved,[id]:false};save();render();document.getElementById(activity.id+'-implementation')?.focus();toast('Kegiatan ditambahkan. Sesuaikan isinya dan lengkapi rencana pelaksanaan.')}
function addActivity(id){data.activities.push({id:'a'+Date.now(),indicator:id,name:'',root:(data.roots[id]||[])[0]||'',target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],budget:0});plannerOpen[id]=1;save();render()}
function finishPlanner(id){const acts=data.activities.filter(a=>a.indicator===id);if(!acts.length)return toast('Pilih atau tambahkan minimal satu kegiatan untuk prioritas ini.');if(acts.some(a=>!activityBasicsValid(a)))return toast('Lengkapi penjelasan implementasi kegiatan. Rincian anggaran dapat dilengkapi nanti.');data.planSaved={...data.planSaved,[id]:true};save();render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});toast('Rencana prioritas tersimpan.')}

function upd(id,k,v){let a=data.activities.find(a=>a.id===id);a[k]=v;save()}
function field(a,k,label,placeholder,type='text'){return `<label for="${a.id}-${k}">${label}</label><input id="${a.id}-${k}" type="${type}" ${type==='number'?'min="0"':''} placeholder="${placeholder}" value="${esc(a[k])}" oninput="upd('${a.id}','${k}',this.value)">`}
function activityForm(a,inline=false){return `<div class="card activity-card guided-activity">${inline?'':`<div class="row"><h3>Kegiatan ${data.activities.filter(x=>x.indicator===a.indicator).indexOf(a)+1}</h3><button class="quiet danger" onclick="removeActivity('${a.id}')">Hapus kegiatan</button></div>`}${a.recommendationKey?(inline?'':`<p class="activity-chosen-name">${esc(a.name)}</p><p class="sub">Menjawab: ${esc(a.root)}</p>`):`${field(a,'name','Nama kegiatan *','Tuliskan kegiatan pilihan sekolah')}<label>Akar masalah yang ingin dijawab *</label><select onchange="upd('${a.id}','root',this.value)">${(data.roots[a.indicator]||[]).map(r=>`<option ${r===a.root?'selected':''}>${esc(r)}</option>`).join('')}</select>`}<label for="${a.id}-implementation">Penjelasan Implementasi Kegiatan *</label><p class="sub" id="${a.id}-implementation-help">Rincian kegiatan yang lebih spesifik sebagai turunan dari kegiatan benahi.</p><textarea id="${a.id}-implementation" aria-describedby="${a.id}-implementation-help" oninput="upd('${a.id}','implementation',this.value)">${esc(a.implementation||'')}</textarea><label class="check"><input type="checkbox" ${a.needsBudget===true?'checked':''} onchange="setActivityCost('${a.id}',this.checked)"><span>Kegiatan ini membutuhkan anggaran</span></label>${a.needsBudget?budgetLineForm(a):''}</div>`}
function setActivityCost(id,value){const a=data.activities.find(a=>a.id===id);a.needsBudget=value;if(value&&!a.budgetLines?.length)a.budgetLines=[{description:'',month:'',quantity:'',unit:'',price:''}];recalculateActivityBudget(a);save();render()}
function recalculateActivityBudget(a){a.budget=a.needsBudget?(a.budgetLines||[]).filter(r=>r.description.trim()).reduce((sum,r)=>sum+(Number(r.quantity)||0)*(Number(r.price)||0),0):0;a.months=a.needsBudget?[...new Set((a.budgetLines||[]).filter(r=>r.description.trim()&&r.month).flatMap(r=>budgetMonths(r.month)))]:[]}
function budgetLineForm(a){return `<section class="activity-budget-lines"><h4>Rincian anggaran kegiatan <span class="budget-optional-label">Opsional</span></h4><p class="sub">Seluruh kolom rincian anggaran bersifat opsional dan dapat dilengkapi nanti. Total dihitung otomatis dari jumlah dan harga satuan yang diisi.</p><div class="budget-lines-scroll"><table><thead><tr><th>Uraian Kegiatan ARKAS</th><th>Bulan Dianggarkan</th><th>Jumlah</th><th>Satuan</th><th>Harga Satuan (Rp)</th><th>Total</th><th></th></tr></thead><tbody>${(a.budgetLines||[]).map((r,j)=>`<tr><td><select aria-label="Uraian Kegiatan ARKAS ${j+1}" onchange="updateBudgetLine('${a.id}',${j},'description',this.value)"><option value="">Pilih uraian</option>${r.description&&!['Uraian 1','Uraian 2','Uraian 3'].includes(r.description)?`<option selected value="${esc(r.description)}">${esc(r.description)}</option>`:''}${['Uraian 1','Uraian 2','Uraian 3'].map(option=>`<option ${r.description===option?'selected':''}>${option}</option>`).join('')}</select></td><td>${budgetMonthPicker(a.id,j,r.month)}</td><td><input aria-label="Jumlah ${j+1}" type="number" min="0" step="any" value="${esc(r.quantity)}" oninput="updateBudgetLine('${a.id}',${j},'quantity',this.value)"></td><td><input aria-label="Satuan ${j+1}" placeholder="Rim, kotak, orang/hari" value="${esc(r.unit)}" oninput="updateBudgetLine('${a.id}',${j},'unit',this.value)"></td><td><input aria-label="Harga Satuan ${j+1}" type="number" min="0" step="any" value="${esc(r.price)}" oninput="updateBudgetLine('${a.id}',${j},'price',this.value)"></td><td><b id="line-total-${a.id}-${j}">${money(Number(r.quantity)*Number(r.price))}</b></td><td><button class="quiet danger" aria-label="Hapus rincian ${j+1}" onclick="removeBudgetLine('${a.id}',${j})">×</button></td></tr>`).join('')}</tbody></table></div><button onclick="addBudgetLine('${a.id}')">＋ Tambah uraian</button><p>Total anggaran kegiatan: <b id="activity-total-${a.id}">${money(a.budget)}</b></p></section>`}
function addBudgetLine(id){const a=data.activities.find(a=>a.id===id);(a.budgetLines??=[]).push({description:'',month:'',quantity:'',unit:'',price:''});save();render()}
function removeBudgetLine(id,index){const a=data.activities.find(a=>a.id===id);a.budgetLines.splice(index,1);recalculateActivityBudget(a);save();render()}
function updateBudgetLine(id,index,key,value){const a=data.activities.find(a=>a.id===id);a.budgetLines[index][key]=value;recalculateActivityBudget(a);save();const r=a.budgetLines[index];document.getElementById('line-total-'+id+'-'+index).textContent=money(Number(r.quantity)*Number(r.price));document.getElementById('activity-total-'+id).textContent=money(a.budget)}

function successForm(a){return `<div class="card activity-card guided-activity"><h3>${esc(a.name||'Kegiatan belum diberi nama')}</h3>${field(a,'target','Perubahan atau hasil yang ingin dicapai *','Contoh: Guru menerapkan hasil refleksi dalam perangkat ajar')}<div class="grid two">${field(a,'quantity','Jumlah yang ditargetkan *','Contoh: 6','number')}${field(a,'unit','Satuan *','Contoh: sesi pendampingan')}</div>${field(a,'proof','Bukti keberhasilan yang akan digunakan *','Contoh: Catatan refleksi dan perubahan perangkat ajar')}<p class="sub">Gunakan bukti dari pekerjaan sehari-hari yang memperlihatkan hasil kegiatan.</p></div>`}
function month(id,m,on){let a=data.activities.find(a=>a.id===id);a.months=on?[...a.months,m]:a.months.filter(x=>x!==m);save()}
function removeActivity(id){const a=data.activities.find(a=>a.id===id);if(a)plannerOpen[a.indicator]=1;data.activities=data.activities.filter(a=>a.id!==id);save();render()}
function back(){if(stage===0)go('home');else{stage--;render();window.scrollTo(0,0)}}
function next(){if(stage===0){if(data.priorities.length<2)return toast('Pilih minimal 2 indikator prioritas.');if(data.priorities.some(id=>!plannerTargetValid(id)))return toast('Lengkapi target capaian untuk setiap indikator pilihan.');}if(stage===1&&data.priorities.some(id=>!(data.roots[id]||[]).length))return toast('Pilih minimal satu akar masalah untuk setiap prioritas.');if(stage===2){if(data.priorities.some(id=>!plannerTargetValid(id))){stage=0;go('flow');toast('Lengkapi target capaian setiap prioritas sebelum menyimpan rencana.');return}if(data.priorities.some(id=>!data.activities.some(a=>a.indicator===id)))return toast('Tambahkan minimal satu kegiatan untuk setiap prioritas.');if(data.activities.some(a=>!activityBasicsValid(a)))return toast('Lengkapi penjelasan implementasi kegiatan. Rincian anggaran dapat dilengkapi nanti.');data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));data.status='Sudah ada rencana';save();go('home');toast('Rencana prioritas berhasil disimpan.');return}if(stage===4){if(!data.evaluationOpen)return toast('Periode evaluasi belum dibuka.');if(data.activities.some(a=>!data.evaluation[a.id]?.result))return toast('Pilih hasil evaluasi untuk setiap kegiatan.');data.evaluationSubmitted=true;save();}if(stage===5){if(data.activities.some(a=>!data.follow[a.id]?.action?.trim()))return toast('Lengkapi rencana tindak lanjut untuk setiap kegiatan.');data.status='Selesai';save();go('detail');toast('Siklus selesai. Pembelajaran tersimpan untuk RKT berikutnya.');return}if(['menetapkan-alternative','menetapkan-cards'].includes(page))page='flow';stage++;render();window.scrollTo(0,0)}
function planSummary(){return reviewCards(true)}
function review(){return `<button class="quiet" onclick="stage=2;go('flow')">← Kembali ke perencanaan</button><div class="flow-heading"><div><div class="eyebrow">Sebelum disimpan</div><h1>Tinjau arah perbaikan sekolah</h1><p class="muted">Pastikan prioritas, akar masalah, dan kegiatan saling terhubung.</p></div><div class="document-status">${badge(data.status)}<span class="save" role="status">✓ Draf tersimpan otomatis</span></div></div><section class="flow-content">${reviewCards()}${budgetReview()}<div class="card review-submit"><div class="row"><span>${data.priorities.length} prioritas · ${data.activities.length} kegiatan</span><b>Total anggaran: ${money(data.activities.reduce((s,a)=>s+Number(a.budget||0),0))}</b></div><div class="line"></div><label class="check"><input id="confirm" type="checkbox"><span>Saya telah meninjau rencana ini dan siap menyimpannya.</span></label><div class="notice warn">Rencana yang disimpan menjadi acuan untuk mencatat capaian, evaluasi, dan tindak lanjut.</div><div class="actions"><button onclick="stage=2;go('flow')">← Perbaiki rencana</button><button class="primary" onclick="submit()">Simpan rencana →</button></div></div></section>`}
function submit(){if(!$('#confirm')?.checked)return toast('Centang pernyataan peninjauan terlebih dahulu.');if(!data.activities.length||data.activities.some(a=>!activityBasicsValid(a)))return toast('Lengkapi rencana kegiatan terlebih dahulu.');data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));data.status='Sudah ada rencana';save();go('home');toast('Rencana prioritas berhasil disimpan.')}
function detail(){return approvedRktView()}
function progressUpdate(id,k,v){const a=data.activities.find(a=>a.id===id);if(k==='achieved'&&v!==''){v=Math.max(0,Number(v)||0)}data.progress[id]={...data.progress[id],[k]:v};if(a){data.progress[id].percent=activityPercent(a);const value=document.getElementById('progress-percent-'+id);if(value)value.textContent=formatProgress(data.progress[id].percent)+'%';const bar=document.getElementById('progress-bar-'+id);if(bar){bar.style.width=data.progress[id].percent+'%';bar.parentElement.setAttribute('aria-valuenow',data.progress[id].percent)}}save()}
function activityPercent(a){const target=Number(a.quantity),actual=Number(data.progress[a.id]?.achieved);if(!Number.isFinite(target)||target<=0||!Number.isFinite(actual))return 0;return Math.min(100,Math.max(0,Math.round(actual/target*1000)/10))}
function formatProgress(value){return new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(value)}
function execution(){return `${data.activities.map(a=>{const p=data.progress[a.id]||{},percent=activityPercent(a);return `<article class="card execution-card"><span class="tag">${esc(ind(a.indicator).name)}</span><h2 style="margin-top:10px">${esc(activitySummaryTitle(a))}</h2><p class="sub">Menjawab: ${esc(a.root)}</p><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}<div class="line"></div><h3>Bukti pelaksanaan <span class="optional-label">Opsional</span></h3><p class="sub">Tambahkan tautan atau lampiran jika tersedia. Anda tetap dapat menyimpan catatan pelaksanaan tanpa bukti.</p><label for="evidence-link-${a.id}">Tautan bukti pelaksanaan <span class="optional-label">(opsional)</span></label><input id="evidence-link-${a.id}" type="url" value="${esc(p.link||'')}" oninput="progressUpdate('${a.id}','link',this.value)" placeholder="https://…"><label for="evidence-file-${a.id}">Lampirkan bukti dari perangkat <span class="optional-label">(opsional)</span></label><input id="evidence-file-${a.id}" type="file" multiple onchange="attach('${a.id}',this.files)"><small>${p.files?.length?'Lampiran tersimpan: '+p.files.map(f=>esc(f.name)).join(', '):'Foto, catatan kegiatan, atau hasil kerja. Maksimal 2 MB per berkas; disimpan di peramban.'}</small><label for="progress-notes-${a.id}" class="execution-notes-label">Catatan kemajuan dan kendala <span class="optional-label">(opsional)</span></label><textarea id="progress-notes-${a.id}" oninput="progressUpdate('${a.id}','notes',this.value)" placeholder="Apa yang sudah berjalan? Dukungan apa yang masih diperlukan?">${esc(p.notes||'')}</textarea></article>`}).join('')}`}
async function attach(id,files){let selected=Array.from(files);if(selected.some(f=>f.size>2*1024*1024))return toast('Ukuran setiap berkas maksimal 2 MB.');let encoded=await Promise.all(selected.map(f=>new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve({name:f.name,url:r.result});r.readAsDataURL(f)})));let old=data.progress[id];data.progress[id]={...old,files:encoded};try{save();toast('Bukti tersimpan di peramban ini.')}catch{data.progress[id]=old;toast('Penyimpanan peramban penuh. Gunakan tautan bukti.')}render()}
function activityPlanContext(a){return `<span class="tag">${esc(ind(a.indicator).name)}</span><h2 style="margin-top:12px">${esc(activitySummaryTitle(a))}</h2><p class="sub">Menjawab: ${esc(a.root)}</p><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}`}
function executionReference(a){const p=data.progress[a.id]||{};const link=typeof p.link==='string'&&/^https?:\/\//i.test(p.link)?p.link:'';return `<section class="execution-reference"><h3>Catatan dan bukti pelaksanaan</h3><p class="sub">Informasi dari tahap Melaksanakan.</p><p class="execution-reference-notes">${esc(p.notes||'Belum ada catatan pelaksanaan.')}</p>${link?`<p><a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Buka tautan bukti pelaksanaan ↗</a></p>`:''}${(p.files||[]).map(f=>`<p><a href="${esc(f.url)}" download="${esc(f.name)}">Unduh bukti: ${esc(f.name)}</a></p>`).join('')}${!link&&!p.files?.length?'<p class="sub">Belum ada bukti pelaksanaan yang dilampirkan.</p>':''}</section>`}
function sourcedIndicatorOutcome(id){const i=ind(id);const year=data.year.split('/')[1];const result=i.annualResults?.[data.year]??i.annualResults?.[year];if(result!==undefined)return result;return String(i.period)===year||String(i.period)===data.year?i.score:undefined}
function dummyIndicatorOutcome(id){const i=ind(id);if(typeof i.score!=='number'||!Number.isFinite(i.score))return undefined;const hash=[...id+data.year].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0);const increase=i.max*(0.08+(hash%1800)/10000);return Math.round(Math.min(i.max,Math.max(0,i.score+increase))*100)/100}
function currentIndicatorOutcome(id){return sourcedIndicatorOutcome(id)??dummyIndicatorOutcome(id)}
function isDummyIndicatorOutcome(id){return sourcedIndicatorOutcome(id)===undefined&&dummyIndicatorOutcome(id)!==undefined}
function indicatorOutcomeValid(id){const v=currentIndicatorOutcome(id);return v!==undefined&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=ind(id).max}
function indicatorOutcomeStatus(id){if(!indicatorOutcomeValid(id))return '<span class="muted">Hasil tahun berjalan belum tersedia</span>';if(!plannerTargetValid(id))return '<span class="muted">Target belum ditetapkan</span>';const diff=Math.round((Number(currentIndicatorOutcome(id))-Number(data.targets[id]))*100)/100;return badge(diff>=0?'Target tercapai':'Belum mencapai target')+'<span>'+scoreText({score:Math.abs(diff)})+' '+(ind(id).unit==='%'?'poin persentase':'poin')+' '+(diff>=0?'di atas / sesuai target':'di bawah target')+'</span>'}
function evaluation(){return data.priorities.map(id=>{const i=ind(id);return `<section class="evaluation-indicator"><article class="card outcome-card compact-evaluation-card"><header class="evaluation-indicator-header"><p class="evaluation-eyebrow">${esc(i.code)} · ${esc(i.source)} · Siklus ${esc(data.year)}</p><h2>${esc(i.name)}</h2></header><div class="evaluation-result-panel"><div class="outcome-grid"><div><span>Capaian awal · ${esc(i.period)}</span><strong>${scoreText(i)} ${esc(i.unit)}</strong></div><div><span>Target · ${esc(data.year)}</span><strong>${plannerTargetValid(id)?scoreText({score:Number(data.targets[id])})+' '+esc(i.unit):'Belum ditetapkan'}</strong></div><div><span>Hasil · ${esc(data.year)}</span><strong>${indicatorOutcomeValid(id)?scoreText({score:Number(currentIndicatorOutcome(id))})+' '+esc(i.unit):'Belum tersedia'}</strong>${isDummyIndicatorOutcome(id)?'<small class="outcome-dummy-note">Data dummy</small>':''}</div></div><div class="outcome-status" id="outcome-status-${id}" aria-live="polite">${indicatorOutcomeStatus(id)}</div></div><div class="indicator-activities">${evaluationActivities(id)}</div></article></section>`}).join('')}
function evaluationActivities(id){const acts=data.activities.filter(a=>a.indicator===id);return acts.map((a,index)=>`<section class="evaluation-activity"><p class="evaluation-eyebrow">Kegiatan pendukung · ${index+1} dari ${acts.length}</p><h3 class="evaluation-activity-title">${esc(activitySummaryTitle(a))}</h3><p class="sub evaluation-root">Menangani ${esc(a.root||'akar masalah belum ditentukan')}</p><details class="evaluation-context"><summary>Lihat implementasi, pelaksanaan, dan anggaran</summary><div class="evaluation-context-body"><span class="evaluation-context-label">Implementasi yang direncanakan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p>${a.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}${executionReference(a)}<span class="evaluation-context-label">Anggaran</span><p>${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</div></details><div class="evaluation-assessment"><label for="evaluation-result-${a.id}">Bagaimana efektivitas kegiatan ini?</label><select id="evaluation-result-${a.id}" required onchange="evalUpd('${a.id}','result',this.value)"><option value="">Pilih hasil evaluasi</option>${['Efektif','Perlu penyesuaian','Tidak efektif'].map(r=>`<option ${data.evaluation[a.id]?.result===r?'selected':''}>${r}</option>`).join('')}</select><label for="evaluation-notes-${a.id}">Alasan penilaian dan pembelajaran</label><textarea id="evaluation-notes-${a.id}" oninput="evalUpd('${a.id}','notes',this.value)" placeholder="Jelaskan perubahan yang terlihat dan bukti pendukungnya.">${esc(data.evaluation[a.id]?.notes||'')}</textarea></div></section>`).join('')}

function evalUpd(id,k,v){data.evaluation[id]={...data.evaluation[id],[k]:v};save()}
function control(){return `<p class="muted">Tentukan tindak lanjut berdasarkan evaluasi. Kegiatan yang perlu penyesuaian atau tidak efektif ditampilkan lebih dahulu; kegiatan efektif tetap dapat dipertahankan.</p>${[...data.activities].sort((a,b)=>(data.evaluation[a.id]?.result==='Efektif')-(data.evaluation[b.id]?.result==='Efektif')).map(a=>`<article class="card execution-card control-card"><span class="tag">${esc(ind(a.indicator).name)}</span><h2 class="control-title">${esc(activitySummaryTitle(a))}</h2><p class="sub control-root">${esc(a.root)}</p><details class="control-plan-details"><summary>Lihat rencana kegiatan${a.needsBudget&&Number(a.budget)>0?' · Anggaran '+money(a.budget):''}</summary><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p>${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</details><div class="control-columns"><section class="evaluation-reference"><h3>Hasil evaluasi</h3>${badge(data.evaluation[a.id]?.result||'Belum dievaluasi')}<p>${esc(data.evaluation[a.id]?.notes||'Belum ada catatan evaluasi.')}</p></section><div class="control-action-form"><label for="follow-type-${a.id}">Jenis tindak lanjut</label><select id="follow-type-${a.id}" onchange="followUpd('${a.id}','type',this.value)">${['Korektif','Preventif','Pemeliharaan','Peningkatan'].map(t=>`<option ${(data.follow[a.id]?.type||(data.evaluation[a.id]?.result==='Efektif'?'Pemeliharaan':'Korektif'))===t?'selected':''}>${t}</option>`).join('')}</select><label for="follow-action-${a.id}">Apa yang akan diperbaiki atau dipertahankan? *</label><textarea id="follow-action-${a.id}" oninput="followUpd('${a.id}','action',this.value)" placeholder="Tuliskan tindak lanjut konkret berdasarkan hasil evaluasi kegiatan ini.">${esc(data.follow[a.id]?.action||'')}</textarea><label class="check"><input type="checkbox" ${data.follow[a.id]?.carry?'checked':''} onchange="followUpd('${a.id}','carry',this.checked)"><span>Bawa kegiatan ke RKT berikutnya sebagai draf yang dapat disesuaikan.</span></label></div></div></article>`).join('')}`}

function followUpd(id,k,v){data.follow[id]={...data.follow[id],[k]:v};save()}
let reportIndicator='lit';
const reportIds=['lit','num','A.3','D.4','D.8','ajar'];
const reportDescriptions={lit:'Kemampuan peserta didik dalam memahami, menggunakan, merefleksi, dan mengevaluasi beragam jenis teks.',num:'Kemampuan peserta didik menggunakan konsep, prosedur, fakta, dan alat matematika untuk menyelesaikan masalah.', 'A.3':'Perkembangan karakter peserta didik dalam sikap, nilai, dan kebiasaan sehari-hari.','D.4':'Kondisi sekolah yang mendukung rasa aman dan melindungi warga sekolah dari kekerasan.','D.8':'Lingkungan belajar yang menghargai perbedaan agama, budaya, dan latar belakang peserta didik.',ajar:'Kualitas praktik pembelajaran yang mendukung keterlibatan dan kebutuhan belajar murid.'};
function reportDelta(i){if(typeof i.previous!=='number'||typeof i.score!=='number')return '<span class="muted">Data pembanding belum tersedia</span>';const d=i.score-i.previous;return `<span class="${d>0?'report-up':d<0?'report-down':'muted'}">${d>0?'↑':d<0?'↓':'−'}</span> Capaian ${d>0?'naik':d<0?'turun':'tidak berubah'}${d!==0?' <b>'+scoreText({score:Math.abs(d)})+' poin</b>':''} dari tahun 2024`}
function reportStatus(i){return `<span class="report-status ${i.color}">${esc(i.level)}${['lit','num'].includes(i.id)?' ('+scoreText(i)+'% murid mencapai kompetensi minimum)':''}</span>`}
function reportComparison(i){return `<div class="report-comparison"><div><span>Capaian tahun 2024</span><b>${typeof i.previous==='number'?scoreText({score:i.previous})+(i.unit?' '+esc(i.unit):''):'Belum tersedia'}</b></div><div><span>Capaian tahun 2025</span><b>${scoreText(i)}${i.unit?' '+esc(i.unit):''}</b></div></div>`}
function reportCard(i,related=false){return `<article class="report-indicator-card"><div class="report-card-content"><h3>${esc(i.name)}</h3>${reportStatus(i)}<p class="report-delta">${reportDelta(i)}</p><button class="report-meaning" onclick="reportMeaning('${i.id}')">ⓘ Apa arti capaian saya?</button><p class="report-compare-label">Perkembangan capaian sekolah</p>${reportComparison(i)}${related?`<p class="report-child-label">Beberapa indikator yang perlu ditingkatkan</p><div class="report-child-list">${i.children.length?i.children.slice(0,2).map((c,j)=>`<div><span>${esc(c.name)}<b>${scoreText(c)}${c.unit?' '+esc(c.unit):''}</b></span><button onclick="reportChildMeaning('${i.id}',${j})">Detail</button></div>`).join(''):'<p class="sub">Belum ada subindikator dalam referensi.</p>'}</div>${i.children.length>2?`<details class="report-more-children"><summary>Lihat ${i.children.length-2} indikator lainnya</summary>${i.children.slice(2).map(c=>`<p>${esc(c.name)} <b>${scoreText(c)} ${esc(c.unit)}</b></p>`).join('')}</details>`:''}`:''}</div>${related?'':`<div class="report-card-footer">${selectable?`<button class="${data.priorities.includes(i.id)?'priority-selected':''}" aria-pressed="${data.priorities.includes(i.id)}" onclick="choose('${i.id}',${!data.priorities.includes(i.id)})">${data.priorities.includes(i.id)?'✓ Dipilih · Batalkan':'Jadikan prioritas'}</button>${data.priorities.includes(i.id)?`<p class="priority-card-target">Target: <b>${esc(data.targets[i.id]??'—')} ${esc(i.unit)}</b> <button class="quiet" onclick="requestPriorityTarget('${i.id}')">Ubah target</button></p>`:''}`:`<button onclick="openReportRoot('${i.id}')">Pelajari Akar Masalah</button>`}</div>`}</article>`}
function reportDialog(){return `<dialog id="report-dialog" class="report-dialog"><div id="report-dialog-content"></div><button class="primary" onclick="document.getElementById('report-dialog').close()">Mengerti</button></dialog>`}
let reportGroupFilter='Semua',reportSort='code',diagnosisSource='Rapor Pendidikan';
function setReportSort(value){reportSort=value;render();document.getElementById('report-indicators')?.scrollIntoView({behavior:'smooth',block:'start'})}
function setReportGroupFilter(value){reportGroupFilter=value;if(page==='rapor'){updateDiagnosisFilters();return}render()}
function reportDimensionGroups(){const topIds=new Set(['lit','num','A.3','D.4','D.8','ajar']);const groups=['Semua','Rekomendasi Indikator',...dimensionNames];const visible=indicators.filter(i=>reportGroupFilter==='Semua'||(reportGroupFilter==='Rekomendasi Indikator'?topIds.has(i.id):dimensionOf(i)===reportGroupFilter));visible.sort((a,b)=>{if(reportSort==='name')return a.name.localeCompare(b.name,'id');if(reportSort==='asc'||reportSort==='desc'){const aValid=typeof a.score==='number',bValid=typeof b.score==='number';if(aValid!==bValid)return aValid?-1:1;if(aValid&&a.score!==b.score)return reportSort==='asc'?a.score-b.score:b.score-a.score;}return a.code.localeCompare(b.code,'id',{numeric:true})});return `<div class="report-group-filters" role="group" aria-label="Filter kelompok indikator">${groups.map(name=>`<button type="button" aria-pressed="${reportGroupFilter===name}" onclick="setReportGroupFilter('${name}')">${esc(name)}</button>`).join('')}</div><div class="report-list-toolbar"><p class="sub report-result-count" role="status">${visible.length} indikator ditampilkan</p><div class="report-sort"><label for="report-sort">Urutkan</label><select id="report-sort" onchange="setReportSort(this.value)">${[['code','Urutan kode'],['name','Nama A–Z'],['asc','Skor terendah'],['desc','Skor tertinggi']].map(([value,label])=>`<option value="${value}" ${reportSort===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="report-dimension-list"><div class="indicator-list">${visible.map(i=>indicatorCard(i,topIds,true)).join('')}</div></div>`}

let diagnosisLayout='grid';
function setDiagnosisLayout(value){if(!['grid','priority','groups'].includes(value))return;diagnosisLayout=value;render()}
function diagnosisReferenceCard(i,selectable=false){const hasScore=typeof i.score==='number',rank=(value)=>value?esc(value):'Data peringkat belum tersedia';const status=['lit','num'].includes(i.id)?`${i.level} (${scoreText(i)}% peserta didik sudah mencapai kompetensi minimum)`:`${i.level||'Capaian'}${hasScore?' · '+scoreText(i)+(i.unit?' '+i.unit:''):''}`;return `<article class="diagnosis-reference-card ${selectable&&data.priorities.includes(i.id)?'priority-card-selected':''}"><div class="diagnosis-reference-body"><div class="diagnosis-card-meta"><span>${esc(i.code)}</span>${['lit','num','A.3','D.4','D.8','ajar'].includes(i.id)?'<span class="diagnosis-priority">Indikator Prioritas</span>':''}</div>${selectable?`<div class="priority-indicator-heading"><h3>${esc(i.name)}</h3>${['Rapor','TKA','Akreditasi'].includes(indicatorSourceLabel(i))?`<p class="priority-source-caption">${esc(i.source==='Rapor Pendidikan'?'Rapor Pendidikan':indicatorSourceLabel(i))}</p>`:''}</div>`:`<h3>${esc(i.name)}</h3>`}<div class="diagnosis-achievement ${hasScore?esc(i.color):'unavailable'}">${esc(hasScore?status:(i.unavailableReason||'Data capaian belum tersedia'))}</div><p class="report-delta">${reportDelta(i)}</p>${selectable||i.source==='Rapor Pendidikan'?`<button class="diagnosis-meaning" onclick="reportMeaning('${i.id}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4C6.5 4 2.2 8.4 1 12c1.2 3.6 5.5 8 11 8s9.8-4.4 11-8c-1.2-3.6-5.5-8-11-8Zm0 13a5 5 0 1 1 0-10 5 5 0 0 1 0 10Zm0-2a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/></svg> Apa arti capaian saya?</button>`:''}<p class="diagnosis-rank-heading">Dibandingkan satuan pendidikan lain</p><div class="diagnosis-rank"><p><strong>${rank(i.rankProvince)}</strong><span>di provinsi</span></p><p><strong>${rank(i.rankNational)}</strong><span>secara nasional</span></p></div><p class="diagnosis-card-source">${esc(i.source)} · ${esc(i.period)}</p></div>${selectable?`<div class="diagnosis-reference-footer">${priorityReferenceFooter(i)}</div>`:['lit','num','A.3','ajar','D.4','D.8'].includes(i.id)?`<div class="diagnosis-reference-footer"><button onclick="openReportRoot('${i.id}')">Pelajari Akar Masalah</button></div>`:''}</article>`}

function diagnosisAlternatives(){if(!['Semua',...dimensionNames].includes(reportGroupFilter))reportGroupFilter='Semua';const visible=diagnosisVisibleIndicators();const cards=diagnosisResultsMarkup(visible);return `<section class="diagnosis-alternatives">${diagnosisSummary()}<div class="diagnosis-alternative-header"><div><h1>Diagnosis</h1><p class="muted">SMA Rakyat 3 · NPSN 20260001 · Tahun data 2025</p></div></div><section id="report-indicators" aria-labelledby="diagnosis-indicators-title"><h2 id="diagnosis-indicators-title" class="diagnosis-indicators-title">Bagaimana situasi yang dihadapi oleh satuan pendidikan saya saat ini?</h2><div class="report-group-filters diagnosis-dimension-tabs" role="group" aria-label="Filter dimensi mutu">${['Semua',...dimensionNames].map(name=>`<button data-diagnosis-dimension="${esc(name)}" aria-pressed="${reportGroupFilter===name}" onclick="setReportGroupFilter('${name}')">${esc(name==='Semua'?'Semua Dimensi':name)}</button>`).join('')}</div><div class="diagnosis-source-toolbar"><span class="diagnosis-source-toolbar-label">Sumber data</span><div class="diagnosis-source-filters" role="group" aria-label="Filter sumber data">${['Rapor Pendidikan','TKA','Akreditasi'].map(source=>`<button type="button" data-diagnosis-source="${source}" aria-pressed="${diagnosisSource===source}" onclick="setDiagnosisSource('${source}')">${source}</button>`).join('')}</div></div><div class="report-list-toolbar"><span class="sub" id="diagnosis-result-count" role="status">${visible.length} indikator ditampilkan</span></div><div id="diagnosis-results">${cards}</div></section><p class="source-text">Data peringkat mengikuti referensi yang tersedia. Peringkat yang belum tersedia tidak diperkirakan. Identitas sekolah digunakan untuk demonstrasi.</p>${reportDialog()}</section>`}

function rapor(){return diagnosisAlternatives()}
function legacyRapor(){return `<div class="diagnosis-legacy-heading"><span class="tag">Alternatif desain · Diagnosis lama</span><button onclick="go('rapor')">Kembali ke Diagnosis utama</button></div><div class="report-school"><div><h2>SMA Rakyat 3</h2><dl><dt>NPSN</dt><dd>20260001 <span class="sub">· Contoh</span></dd><dt>Tahun data</dt><dd>2025</dd><dt>Satuan pendidikan</dt><dd>SMA · Data demonstrasi</dd></dl></div><div class="report-accreditation"><span>ⓘ Akreditasi</span><div>A</div></div></div><section id="report-indicators" class="report-indicators-section"><h2>Kondisi mutu satuan pendidikan</h2><p class="sub">Lihat seluruh indikator atau pilih kelompok mutu untuk melihat capaian dan subindikatornya.</p>${reportDimensionGroups()}</section><div class="report-download"><div><h3>Pelajari capaian sekolah secara menyeluruh</h3><p class="sub">Unduh data indikator utama dan subindikator untuk membantu refleksi bersama guru.</p></div><button onclick="downloadReport()">Unduh data indikator ↓</button></div><p class="source-text">Referensi data: Laporan Rapor Pendidikan Barokatul Huda tahun 2025, diperbarui 16 Juni 2026. Identitas SMA Rakyat 3 digunakan untuk demonstrasi. Data TKA dan akreditasi tetap berupa contoh terpisah.</p>${reportDialog()}`}
function openReportRoot(id){reportIndicator=id;go('rapor-root')}
function reportRelated(i){const codes=new Set(i.roots.map(r=>r.split(' · ')[0]).map(code=>code.split('.').slice(0,2).join('.')));const all=indicators.filter(r=>r.source==='Rapor Pendidikan'&&codes.has(r.code)&&r.id!==i.id);return all.length?all.slice(0,3):['ajar','D.2','D.3'].map(ind).filter(r=>r.id!==i.id)}
function rcRank(v){return v?esc(v):'Data peringkat belum tersedia'}
function rcRule(t){return `<div class="rc-rule"><span>${t}</span><i></i></div>`}
function rcComparison(i){return `<div class="rc-comparison">${rcRule('Dibandingkan Satdik lain, Satdik Anda termasuk')}<ul class="rc-rank"><li><p><strong>${rcRank(i.rankProvince)}</strong> di provinsi</p></li><li><p><strong>${rcRank(i.rankNational)}</strong> secara nasional</p></li></ul></div>`}
function rcScoreList(i,limit){const kids=i.children||[];if(!kids.length)return '<p class="rc-empty">Belum ada subindikator dalam referensi.</p>';const row=(c,j)=>`<li class="rc-score-row"><div class="rc-score-text"><p class="rc-score-name">${esc(c.name)}</p><p class="rc-score-value"><strong>${scoreText(c)}</strong>${c.unit?' '+esc(c.unit):''}</p></div><button type="button" class="rc-trigger" onclick="reportChildMeaning('${i.id}',${j})">Detail</button></li>`;const shown=kids.slice(0,limit).map(row).join('');const rest=kids.length-limit;return `<ul class="rc-score-list">${shown}</ul>${rest>0?`<details class="rc-more"><summary>Lihat ${rest} indikator lainnya<img src="assets/akar/keyboard-arrow-right.svg" width="24" height="24" alt=""></summary><ul class="rc-score-list">${kids.slice(limit).map((c,j)=>row(c,j+limit)).join('')}</ul></details>`:''}`}
function rcHead(i,main){return `<div class="rc-head"><h4 class="rc-card-name">${esc(i.name)}</h4><div class="rc-progress">${reportStatus(i)}<p class="report-delta">${reportDelta(i)}</p></div><div class="rc-triggers"><button type="button" class="rc-trigger" onclick="reportMeaning('${i.id}')">Apa arti capaian saya?</button></div></div>`}
function rcReflection(){const L=[['8a10c','48.11% 0 32.44% 8.44%'],['51473','0 0 0 3.99%'],['f4ae2','36.13% 29.72% 28.41% 61.29%'],['2092b','4.1% 15.51% 50.32% 64.69%'],['12fe3','41.5% 6.78% 0 59.1%'],['3e9b5','97.95% 35.01% 0 60.29%'],['495b0','46.32% 15.66% 0 58.87%'],['efdc4','3.92% 45.75% 3.38% 19.94%'],['c76a9','6.72% 46.88% 6.18% 21.06%'],['9e435','57.12% 46.88% 6.18% 21.06%','0px -112.891px'],['7a768','80.15% 46.88% 10.64% 44.95%','-93.156px -164.469px'],['61094','6.72% 46.88% 26.75% 21.06%','-0.008px 0.01px'],['52888','10.35% 41.03% 4.72% 21.06%','0px -8.135px'],['a39c9','4.08% 46.88% 3.7% 18.84%'],['efcf4','5.14% 45.66% 73.54% 43.11%']];const mask='url(assets/hero/c2326.svg)';return L.map(l=>`<div class="rc-layer" style="inset:${l[1]};${l[2]?`-webkit-mask-image:${mask};mask-image:${mask};-webkit-mask-size:125.03px 195.099px;mask-size:125.03px 195.099px;-webkit-mask-position:${l[2]};mask-position:${l[2]};-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;`:''}"><img src="assets/hero/${l[0]}.svg" alt="" draggable="false"></div>`).join('')}
function rcIcon(n,w=24){return `<img src="assets/rekom/${n}.svg" width="${w}" height="${w}" alt="">`}
function rcInspirations(c){const items=[['Pelajari strategi pembelajaran melalui komunitas belajar guru.','info-1','primary'],['Uji strategi di kelas, lalu refleksikan hasilnya bersama rekan guru.','kelas-1','success'],['Siapkan dukungan waktu dan sumber daya agar perbaikan berkelanjutan.','dukungan-1','warning']];return items.map((t,j)=>`<li class="rc-card"><div class="rc-card-copy"><p class="rc-card-eyebrow">Inspirasi ${j+1}</p><p class="rc-card-text">${t[0]}</p></div><div class="rc-thumb"><img src="assets/rekom/${t[1]}.png" width="64" height="64" alt=""><span class="rc-thumb-mark ${t[2]}"></span></div></li>`).join('')}
function rcPanel(c,g){const safe=esc(c.name);return `<article class="rc-panel"><div class="rc-panel-copy"><p class="rc-eyebrow-sm">Membenahi</p><h4 class="rc-panel-title">${safe}</h4><p class="rc-panel-desc">Mulai dari hasil asesmen dan pengamatan kelas. Diskusikan kebutuhan murid, pilih perbaikan praktik mengajar, lalu amati perubahan yang terjadi.</p></div><div class="rc-highlight"><img class="rc-sparkle" src="assets/rekom/sparkle-orange.svg" width="22" height="22" alt=""><p>Salah satu upaya yang bisa dilakukan adalah <strong>memulai dari hasil asesmen dan pengamatan kelas terkait ${safe.toLowerCase()}</strong>. Berikut beberapa cara konkret yang bisa dijadikan inspirasi:</p></div><div class="rc-carousel"><ul class="rc-cards" tabindex="0" aria-label="Daftar inspirasi" onscroll="rcSync(this)">${rcInspirations(c)}</ul><div class="rc-controls"><div class="rc-pagination"><button type="button" class="rc-arrow" data-dir="-1" onclick="rcSlide(this,-1)" aria-label="Inspirasi sebelumnya" disabled>${rcIcon('chevron-left')}</button><div class="rc-dots">${[0,1,2].map(k=>`<button type="button" class="rc-dot" onclick="rcSlideTo(this,${k})" aria-label="Inspirasi ${k+1}" ${k===0?'aria-current="true"':''}>${rcIcon(k===0?'toggle-active':'toggle-inactive',20)}</button>`).join('')}</div><button type="button" class="rc-arrow flip" data-dir="1" onclick="rcSlide(this,1)" aria-label="Inspirasi berikutnya">${rcIcon('chevron-right')}</button></div><button type="button" class="rc-cta" onclick="rcMaterials('${safe.replace(/'/g,"\\'")}')">Cek Materi</button></div></div></article>`}
function rcRecommendations(i,related){const groups=[i,...related];return `<section id="report-inspiration" class="rc-reco"><div class="rc-reco-inner"><div class="rc-reco-title">${rcIcon('sparkle-white')}<h2>Inspirasi cara membenahi ${esc(i.name)}</h2></div><div class="rc-reco-groups">${groups.map((r,j)=>`<section class="rc-acc"><div class="rc-acc-head"><h3>${esc(r.name)}</h3><div class="rc-acc-right">${reportStatus(r)}<img src="assets/rekom/divider.svg" width="1" height="26" alt=""><button type="button" class="rc-acc-toggle" aria-expanded="${j===0}" aria-controls="rc-panels-${j}" onclick="rcToggle(this)"><span>${j===0?'Tutup Detail':'Buka Detail'}</span>${rcIcon('expand-more')}</button></div></div><div id="rc-panels-${j}" class="rc-panels" ${j===0?'':'hidden'}>${(r.children.length?r.children:[{name:r.name}]).slice(0,2).map(c=>rcPanel(c,r)).join('')}</div></section>`).join('')}</div></div></section>`}
function rcToggle(b){const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.querySelector('span').textContent=open?'Tutup Detail':'Buka Detail';document.getElementById(b.getAttribute('aria-controls')).hidden=!open}
function rcSync(list){const step=422,atEnd=list.scrollLeft+list.clientWidth>=list.scrollWidth-2,n=list.children.length,idx=atEnd?n-1:Math.round(list.scrollLeft/step);const box=list.closest('.rc-carousel');box.querySelectorAll('.rc-dot').forEach((d,k)=>{const on=k===idx;if(on)d.setAttribute('aria-current','true');else d.removeAttribute('aria-current');d.querySelector('img').src='assets/rekom/'+(on?'toggle-active':'toggle-inactive')+'.svg'});box.querySelector('.rc-arrow:not(.flip)').disabled=idx===0;box.querySelector('.rc-arrow.flip').disabled=idx===n-1}
function rcSlideTo(btn,k){const list=btn.closest('.rc-carousel').querySelector('.rc-cards');list.scrollTo({left:k*422,behavior:'smooth'})}
function rcSlide(btn,d){const list=btn.closest('.rc-carousel').querySelector('.rc-cards');const cur=Math.round(list.scrollLeft/422);list.scrollTo({left:Math.max(0,Math.min(list.children.length-1,cur+d))*422,behavior:'smooth'})}
function rcMaterials(name){const items=['Strategi mengajar di kelas','Panduan diskusi bersama rekan guru','Contoh praktik baik dari sekolah lain'];document.getElementById('report-dialog-content').innerHTML=`<p class="rc-eyebrow-sm">Materi pendukung</p><h2>${name}</h2><ol class="rc-materials">${items.map((t,k)=>`<li><span class="rc-material-no" aria-hidden="true">${k+1}</span><span>${t}</span></li>`).join('')}</ol><p class="sub">Contoh daftar materi. Tautan materi sebenarnya belum tersedia di prototipe.</p>`;document.getElementById('report-dialog').showModal()}
function raporRoot(){const i=ind(reportIndicator),related=reportRelated(i);const desc=reportDescriptions[i.id]||i.desc;return `<section class="rc-header"><div class="rc-inner"><nav class="rc-breadcrumb" aria-label="Breadcrumb"><button type="button" onclick="go('rapor')">Ringkasan</button><img src="assets/header/chevron-right.svg" width="24" height="24" alt=""><span aria-current="page">${esc(i.name)}</span></nav><div class="rc-header-content">${i.id==='lit'?'<img class="rc-header-art" src="assets/header/img-literasi.svg" width="84" height="84" alt="">':''}<div class="rc-header-copy"><div class="rc-titles"><p class="rc-eyebrow">Pelajari Akar Masalah dari</p><h1>${esc(i.name)}</h1></div><p class="rc-desc">${esc(desc)}</p></div></div></div></section><div class="rc-tabbar"><nav class="rc-tabs" aria-label="Bagian halaman"><button type="button" class="active" onclick="reportSection('report-root-factors',this)"><span>Akar Masalah</span><i></i></button><button type="button" onclick="reportSection('report-inspiration',this)"><span>Inspirasi Benahi</span><i></i></button></nav></div><section id="report-root-factors" class="rc-section"><div class="rc-content"><h2 class="rc-question">Apa saja faktor yang memengaruhi ${esc(i.name)} satuan pendidikan saya?</h2><div class="rc-group"><h3 class="rc-group-title">Subindikator dari ${esc(i.name)}</h3><div class="rc-main"><article class="rc-main-card">${rcHead(i,true)}${rcComparison(i)}</article><div class="rc-list-panel"><div class="rc-list-content">${rcRule('Beberapa subindikator yang perlu ditingkatkan')}${rcScoreList(i,3)}</div></div></div></div><div class="rc-group"><h3 class="rc-group-title">Faktor dari indikator lain yang memengaruhi capaian indikator prioritas</h3><div class="rc-related">${related.map(r=>`<article class="rc-related-card">${rcHead(r)}${rcComparison(r)}<div class="rc-related-list">${rcRule('Beberapa subindikator yang perlu ditingkatkan')}${rcScoreList(r,2)}</div></article>`).join('')}</div></div></div><div class="rc-download"><div class="rc-download-inner"><div class="rc-download-copy"><h3>Unduh data indikator untuk melihat capaian dan subindikator</h3><p>Gunakan sebagai bahan diskusi dan refleksi bersama warga sekolah.</p></div><button type="button" class="rc-download-btn" onclick="downloadReport()"><span>Unduh data indikator</span><img src="assets/akar/arrow-right.svg" width="20" height="20" alt=""></button></div></div></section><section class="rc-reflection" aria-labelledby="rc-reflection-title"><div class="rc-illustration" aria-hidden="true">${rcReflection()}</div><h2 id="rc-reflection-title">Mari berhenti dan berpikir sejenak...</h2><ul class="rc-dialogue"><li>Seberapa sering guru membahas hasil asesmen murid bersama?</li><li>Dukungan apa yang sudah diberikan sekolah untuk meningkatkan ${esc(i.name.toLowerCase())}?</li></ul></section>${rcRecommendations(i,related)}${reportDialog()}`}
function reportSection(id,button){document.querySelectorAll('.rc-tabs button').forEach(b=>b.classList.toggle('active',b===button));document.getElementById(id).scrollIntoView({behavior:'smooth',block:'start'})}
function reportMeaning(id){const i=ind(id);document.getElementById('report-dialog-content').innerHTML=`<span class="tag">${esc(i.code)}</span><h2>${esc(i.name)}</h2><p>${esc(i.definition||reportDescriptions[id]||i.desc)}</p><div class="line"></div><p><b>Capaian 2025: ${scoreText(i)} ${esc(i.unit)}</b></p><p>${esc(i.achievementDefinition||i.unavailableReason)}</p>${i.average?`<p>Nilai rerata (berbeda dari persentase murid): <b>${scoreText(i.average)}</b></p>`:''}<p>Kategori pada data referensi: <b>${esc(i.level)}</b>.</p>${['lit','num'].includes(id)?'<p>Persentase menunjukkan proporsi murid yang mencapai kompetensi minimum pada indikator ini.</p>':''}<p class="sub">Gunakan capaian ini bersama subindikator dan bukti dari sekolah untuk memahami area perbaikan.</p>`;document.getElementById('report-dialog').showModal()}
function reportChildMeaning(id,index){const i=ind(id),c=i.children[index];document.getElementById('report-dialog-content').innerHTML=`<span class="tag">${esc(c.code)}</span><h2>${esc(c.name)}</h2><p>Bagian dari indikator ${esc(i.name)}.</p><p>${esc(c.definition)}</p><div class="line"></div><p><b>Capaian 2025: ${scoreText(c)} ${esc(c.unit)}</b></p><p class="sub">Sumber: ${esc(c.source)}. ${c.level?'Kategori: '+esc(c.level)+'.':''}</p>`;document.getElementById('report-dialog').showModal()}
let downloadYear='2026';
function setDownloadYear(value){if(!['2026','2025'].includes(value))return;downloadYear=value;render()}
function downloadSelectedReport(){if(downloadYear!=='2025')return;downloadReport()}
function downloadsPage(){const available=downloadYear==='2025';return `<section class="download-page"><article class="download-report-card"><h2>Laporan Rapor Pendidikan</h2><p class="download-intro">Laporan hanya tersedia untuk satuan pendidikan yang mengikuti Asesmen Nasional (AN).</p>${available?'<div class="download-available"><b>Data Rapor Pendidikan Tahun 2025 tersedia</b><p>Unduh data indikator utama dan subindikator yang digunakan dalam prototipe ini dalam format CSV.</p></div>':`<div class="download-unavailable" role="status"><h3><span aria-hidden="true">⚠</span> Rapor Pendidikan Tahun ${downloadYear} Tidak Tersedia</h3><p>Data tahun ${downloadYear} belum tersedia di prototipe ini. Pilih tahun 2025 untuk mengunduh data indikator yang tersedia.</p></div>`}<div class="download-controls"><div><label for="download-year">Pilih Tahun Data</label><select id="download-year" onchange="setDownloadYear(this.value)"><option value="2026" ${!available?'selected':''}>2026</option><option value="2025" ${available?'selected':''}>2025</option></select></div><button class="primary" ${available?'':'disabled'} onclick="downloadSelectedReport()">Unduh Rapor Pendidikan</button></div><details class="download-learning"><summary>Pelajari Rapor Pendidikan & Perencanaan Berbasis Data</summary><p>Gunakan halaman Diagnosis untuk memahami capaian sekolah dan akar masalah. Lanjutkan ke Siklus 6M untuk menetapkan prioritas, menyusun kegiatan, menjalankan, mengevaluasi, dan menindaklanjuti perbaikan.</p><button onclick="go('rapor')">Buka Diagnosis</button></details></article><article class="download-poster-card"><div class="download-poster-copy"><h2>Poster Rapor Pendidikan</h2><p>Membenahi akar masalah akan lebih efektif jika dilakukan bersama-sama. Bagikan ringkasan capaian kepada warga sekolah untuk mendukung perbaikan bersama.</p><button disabled>Unduh Poster</button><p class="download-poster-note">Poster sekolah belum tersedia di prototipe ini.</p></div><div class="download-poster-art" aria-label="Ilustrasi poster Rapor Pendidikan"><div class="download-mini-poster"><div class="mini-poster-brand">Rapor Pendidikan</div><b>Ringkasan capaian sekolah</b><div class="mini-poster-grid">${['Literasi','Numerasi','Karakter','Keamanan','Kebinekaan','Pembelajaran'].map((name,j)=>`<div><span>${name}</span><i class="${[2,5].includes(j)?'mini-amber':'mini-red'}"></i><small>Capaian sekolah</small></div>`).join('')}</div><div class="mini-poster-footer">Dari data, menjadi perubahan nyata.</div><div class="mini-poster-people" aria-hidden="true">● ● ●</div></div></div></article></section>`}

function downloadReport(){const rows=[['Kode','Indikator','Induk','Skor 2025','Satuan','Kategori','Sumber'],...indicators.filter(i=>i.source==='Rapor Pendidikan').flatMap(i=>{return [[i.code,i.name,'',i.score,i.unit,i.level,i.origin],...i.children.map(c=>[c.code,c.name,i.code,c.score,c.unit,c.level,c.source])]})];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='rapor-pendidikan-sma-rakyat-3-2025.csv';link.click();URL.revokeObjectURL(url);toast('Data indikator siap diunduh.')}
function help(){return `<h1>Pusat Bantuan</h1><p class="muted">Panduan singkat menyusun dan menjalankan Rencana Kerja Tahunan.</p>${[['Apa itu Siklus 6M?','Siklus 6M membantu sekolah memperbaiki mutu melalui enam tahap: Menetapkan prioritas dan target, Memetakan akar masalah, Merencanakan kegiatan, Melaksanakan kegiatan, Mengevaluasi hasil, dan Mengendalikan perbaikan untuk siklus berikutnya.'],['Kapan RKT disusun?','RKT disusun untuk satu tahun ajaran, dari Juli hingga Juni. Anda dapat menyimpan draf dan melanjutkannya kembali.'],['Berapa indikator yang perlu dipilih?','Pilih 2–3 indikator prioritas dari sumber data mana pun. Setiap indikator perlu memiliki target dan minimal satu kegiatan.'],['Kapan rencana dapat diperbaiki?','Rencana dapat dilengkapi saat berstatus Draf. Simpan rencana prioritas pada tahap Merencanakan untuk mulai mencatat capaian.'],['Kapan capaian dapat dimasukkan?','Setelah rencana prioritas disimpan. Status menjadi Sudah ada rencana dan tombol Masukkan capaian tersedia di daftar siklus.'],['Bagaimana menggunakan menu demo?','Klik Menu demo di pojok kanan bawah. Anda dapat berpindah tahap, mengisi contoh rencana, dan mencoba status draf, pelaksanaan, evaluasi, dan tindak lanjut. Semua simulasi hanya tersimpan di peramban ini.']].map(([q,a])=>`<details class="card"><summary><b>${q}</b></summary><p class="muted" style="margin-top:15px">${a}</p></details>`).join('')}`}
const demoStatuses=[['draft','Draf — rencana belum disimpan'],['active','Sudah ada rencana — masukkan capaian'],['evaluation-open','Masa evaluasi'],['followup','Evaluasi selesai — tindak lanjut'],['completed','Selesai']];
function resetSelfEvaluationDemo(){reflections={};reflectionYear='';reflectionStep=0;localStorage.removeItem('spmp-self-reflections-v1');demo=false;go('self-evaluation');toast('Evaluasi diri direset. Data siklus tetap tersimpan.')}
function demoPanel(){return `<aside class="demo-panel" aria-label="Menu demo"><div class="eyebrow">Ruang simulasi</div><h3>Jelajahi prototipe</h3><p class="sub">Pilihan skenario mengganti isian siklus saat ini dengan data contoh dan membuka tahap yang dipilih. Tidak ada data yang dikirim.</p><section class="demo-section"><h4>Halaman utama</h4>${localDesignAlternatives()?`<button onclick="demo=false;go('diagnosis-alternatives')">Design alternatives: Diagnosis lama</button>`:''}<button onclick="demo=false;go('rapor')">Diagnosis</button><button onclick="demo=false;go('home')">Daftar siklus</button><button onclick="demo=false;go('self-evaluation')">Daftar evaluasi diri</button></section><section class="demo-section"><h4>Alur Siklus 6M</h4>${localDesignAlternatives()?`<button onclick="openMenetapkanAlternative()">Design alternatives: Menetapkan lama</button><button onclick="openMenetapkanCards()">Design alternatives 2</button>`:''}${names.map((n,i)=>`<button onclick="jump(${i})">${i+1}. ${n}</button>`).join('')}<button onclick="demoReview()">Tinjau rencana (demo)</button></section><section class="demo-section"><h4>Status siklus</h4>${demoStatuses.map(([s,t])=>`<button onclick="simulate('${s}')">${t}</button>`).join('')}</section><section class="demo-section"><h4>Skenario evaluasi diri</h4><button onclick="demoReflection('start')">Mulai evaluasi diri</button><button onclick="demoReflection('review')">Tinjau perbedaan penilaian</button><button onclick="demoReflection('saved')">Hasil tersimpan · hanya lihat</button><button onclick="resetSelfEvaluationDemo()">Reset Evaluasi Diri</button></section><section class="demo-section"><h4>Atur ulang</h4><button onclick="simulate('empty')">Belum ada siklus baru</button><button class="danger" onclick="resetDemo()">Atur ulang seluruh data demo</button></section></aside>`}
function toggleDemo(){demo=!demo;render()}
function ensureSample(){if(data.priorities.length<2){data.priorities=['lit','num'];data.targets={lit:35,num:50};}data.priorities.forEach((id,j)=>{if(!data.targets[id])data.targets[id]=Math.min(ind(id).max,(typeof ind(id).score==='number'?ind(id).score:0)+15);if(!data.roots[id]?.length)data.roots[id]=ind(id).roots.length?[ind(id).roots[0]]:['Hasil pengamatan sekolah perlu ditelaah bersama'];if(!data.activities.some(a=>a.indicator===id))data.activities.push({id:'demo-'+id,indicator:id,name:id==='lit'?'Pendampingan guru untuk pembelajaran literasi':id==='num'?'Pembelajaran numerasi berbasis masalah sehari-hari':'Komunitas belajar untuk '+ind(id).name,root:data.roots[id][0],implementation:j?'Guru merancang dan mencoba pembelajaran numerasi dengan masalah sehari-hari, kemudian membahas hasilnya dalam komunitas belajar.':'Guru mengikuti pendampingan membaca teks informasi bersama dua guru inti melalui komunitas belajar sekolah.',target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],needsBudget:j===0,budget:j===0?2500000:0,budgetLines:j===0?[{description:'Bahan pendampingan dan bacaan',month:'Agu',quantity:25,unit:'paket',price:100000}]:[]})});prepareSampleActivityForms();save()}
function prepareDemo(){const year=data.year;data=seed();data.year=year;ensureSample();data.status='Draf';data.budget='Belum diisi';data.evaluationOpen=false;data.evaluationSubmitted=false;data.revisionKind=null;data.planSaved={};demo=false}
function prepareSampleActivityForms(){data.activities.forEach(a=>{if(a.implementation===undefined)a.implementation=a.realistic||a.name;if(a.needsBudget===undefined){a.needsBudget=Number(a.budget)>0;a.budgetLines=a.needsBudget?[{description:'Pendukung kegiatan',month:a.months[0]||'Agu',quantity:1,unit:'paket',price:Number(a.budget)}]:[]}})}
function seedDemoProgress(){data.activities.forEach((a,j)=>{data.progress[a.id]={notes:j?'Pembelajaran mulai dicoba di kelas. Diskusi refleksi perlu penyesuaian jadwal.':'Pendampingan berjalan sesuai rencana. Guru mulai menggunakan teks informasi dalam pembelajaran.',link:'',files:[]}})}
function seedDemoEvaluation(){data.activities.forEach((a,j)=>data.evaluation[a.id]={result:j?'Perlu penyesuaian':'Efektif',notes:j?'Jadwal kegiatan perlu disesuaikan dengan beban mengajar.':'Guru mulai menerapkan hasil pendampingan dalam pembelajaran.'})}
function demoReview(){prepareDemo();save();go('review')}
function jump(i){if(!Number.isInteger(i)||i<0||i>5)return;prepareDemo();if(i<=2){data.activities=[];data.planSaved={};if(i===0){data.priorities=[];data.targets={};data.roots={}}if(i===1)data.roots={};}if(i>=3){data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));seedDemoProgress()}if(i>=4)data.evaluationOpen=true;if(i===5){data.evaluationSubmitted=true;seedDemoEvaluation()}stage=i;save();go('flow')}
function simulate(s){if(s!=='empty'&&!demoStatuses.some(([key])=>key===s))return;prepareDemo();if(s==='empty'){const year=data.year;data=seed();data.year=year}else if(['active','evaluation-open','followup','completed'].includes(s)){data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));seedDemoProgress();if(s!=='active')data.evaluationOpen=true;if(s==='followup'||s==='completed'){data.evaluationSubmitted=true;seedDemoEvaluation()}if(s==='completed'){data.status='Selesai';data.activities.forEach(a=>data.follow[a.id]={type:'Korektif',action:'Lanjutkan kegiatan dengan penyesuaian jadwal dan diskusikan hasilnya bersama guru.',carry:true})}}save();go('home')}
function demoReflection(mode){if(!['start','review','saved'].includes(mode))return;simulate('completed');const year=data.year,ev=reflectionEvidence(data);const r={scores:{},notes:{},justifications:{},completed:false};if(mode!=='start'){ev.forEach((e,i)=>r.scores[i]=e.score);r.scores[1]=Math.max(0,ev[1].score-1);r.scores[2]=Math.min(3,ev[2].score+1)}if(mode==='saved'){r.justifications[1]='Sekolah masih perlu memverifikasi akar masalah melalui diskusi guru sebelum menilai praktik ini lebih tinggi.';r.justifications[2]='Sekolah telah meninjau rancangan anggaran bersama tim, tetapi catatannya belum dimasukkan ke prototipe.';r.completed=true;r.evidenceSnapshot=ev;r.savedAt=new Date().toISOString()}reflections[year]=r;reflectionSave();page='self-evaluation';reflectionYear=mode==='saved'?'':year;reflectionStep=mode==='start'?0:6;demo=false;render();window.scrollTo(0,0)}

function resetDemo(){if(!confirm('Hapus semua isian siklus, lampiran, dan evaluasi diri demo di peramban ini?'))return;data=seed();history=[];reflections={};reflectionYear='';reflectionStep=0;localStorage.removeItem('spmp-history-spreadsheet-v3');localStorage.removeItem('spmp-self-reflections-v1');save();go('home');toast('Seluruh data demo telah diatur ulang. Riwayat contoh bawaan tetap tersedia.')}
function archive(){const current=data;data={...seed(),year:'2026/2027',priorities:['lit','num'],targets:{lit:70,num:75},roots:{lit:[ind('lit').roots[0]],num:[ind('num').roots[0]]},status:'Selesai',budget:'Disetujui'};page='detail';render();data=current;$('.wrap').insertAdjacentHTML('afterbegin','<div class="notice">Riwayat contoh tahun ajaran 2026/2027 · Arsip hanya dapat dilihat.</div>')}
render();

function newCycle(){let old=JSON.parse(JSON.stringify(data));history.push(old);localStorage.setItem('spmp-history-spreadsheet-v3',JSON.stringify(history));let year=Number(old.year.split('/')[0])+1;data=seed();data.year=year+'/'+(year+1);data.activities=old.activities.filter(a=>old.follow[a.id]?.carry).map(a=>({...a,id:'next-'+a.id}));data.priorities=[...new Set(data.activities.map(a=>a.indicator))];data.priorities.forEach(id=>{data.roots[id]=old.roots[id];data.custom[id]=old.custom[id]||[]});save();start();toast('Draf tahun berikutnya dibuat. Tinjau kembali prioritas, target, dan kegiatan.')}
function viewHistory(i){const current=data;data=history[i];page='detail';render();data=current;document.querySelector('.wrap').insertAdjacentHTML('afterbegin','<div class="notice">Arsip siklus sekolah · Hanya dapat dilihat.</div>')}

function scoreText(i){return typeof i.score==='number'?new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(i.score):i.score===null?'Tidak tersedia':esc(i.score)}
function referenceDetails(i){return `<p class="source-text">${esc(i.origin)} · ${esc(i.period)}${typeof i.previous==='number'&&typeof i.score==='number'?` · Perubahan ${new Intl.NumberFormat('id-ID',{signDisplay:'always',maximumFractionDigits:2}).format(i.score-i.previous)} poin dari 2024`:''}</p>${i.children.length?`<div class="line"></div><b class="sub">Subindikator</b>${i.children.map(c=>`<div class="listitem"><span class="source-text">${esc(c.code)}</span> ${esc(c.name)}<br><b>${scoreText(c)} ${esc(c.unit)}</b>${c.level?' · '+esc(c.level):''}</div>`).join('')}`:''}`}

function chosenPanel(){return `<aside class="chosen-panel"><div class="card"><div class="row"><h3>Prioritas pilihan Anda</h3><span class="badge blue">${data.priorities.length}/3</span></div>${data.priorities.length?data.priorities.map(id=>`<div class="chosen-item"><span>${esc(ind(id).name)}</span><span class="chosen-target"><b>${scoreText(ind(id))}${ind(id).unit?' '+esc(ind(id).unit):''} → ${esc(data.targets[id]??'—')}${esc(ind(id).unit)}</b><button class="quiet" onclick="requestPriorityTarget('${id}')">Ubah target</button></span><button class="remove-priority" aria-label="Hapus prioritas ${esc(ind(id).name)}" title="Hapus prioritas" onclick="choose('${id}',false)">×</button></div>`).join(''):'<p class="sub">Belum ada indikator dipilih.</p>'}<div class="chosen-actions"><button class="primary" onclick="next()">Lanjutkan →</button><button onclick="save();go('home')">Simpan draf & keluar</button></div></div></aside>`}

function activitySummaryTitle(a){if(!a.recommendationKey)return a.name;const parts=a.recommendationKey.split(':');const index=Number(parts[2]);const topics={'A.1.1':'membaca teks informasi','A.2.1':'domain bilangan','D.3.1':'visi-misi satuan pendidikan','D.8.1':'toleransi agama dan budaya','D.6.1':'kesetaraan gender','D.4.8':'pencegahan dan penanganan kekerasan seksual','D.1.2':'dukungan psikologis','A.3.5':'kebinekaan global'};const topic=topics[parts[1]];if(!topic)return a.name;if(parts[1]==='D.3.1')return ['Penyelarasan visi-misi satuan pendidikan','Penerjemahan visi-misi ke dalam pembelajaran','Refleksi penerapan visi-misi sekolah'][index]||a.name;if(index===0)return 'Peningkatan kompetensi dalam '+topic;if(index===1)return 'Penerapan '+topic+' dalam pembelajaran';if(index===2)return 'Penguatan program dan kebijakan tentang '+topic;if(index===3&&parts[1]==='A.1.1')return 'Pemenuhan buku teks dan bahan bacaan';return a.name}
function activityBudgetSummary(a){if(!a.needsBudget)return 'Tidak membutuhkan anggaran';const lines=a.budgetLines||[];const started=lines.filter(r=>r.description.trim());if(!started.length)return 'Membutuhkan anggaran <span class="sub">· Rincian anggaran belum diisi</span>';const incomplete=started.some(r=>!r.month||!r.quantity||!r.unit.trim()||r.price==='');return 'Membutuhkan anggaran <span class="sub">· '+(incomplete?'Rincian anggaran belum lengkap':money(a.budget))+'</span>'}
function savedActivityBudgetDetails(a){const lines=(a.budgetLines||[]).filter(r=>Object.values(r).some(v=>String(v??'').trim()));if(!a.needsBudget||!lines.length)return '';return `<details class="saved-budget-details"><summary>Lihat detail anggaran</summary><div class="budget-lines-scroll"><table><thead><tr><th>Uraian Kegiatan ARKAS</th><th>Bulan Dianggarkan</th><th>Jumlah</th><th>Satuan</th><th>Harga Satuan</th><th>Total</th></tr></thead><tbody>${lines.map(r=>`<tr><td>${esc(r.description||'—')}</td><td>${esc(r.month||'—')}</td><td>${esc(r.quantity||'—')}</td><td>${esc(r.unit||'—')}</td><td>${r.price!==''&&r.price!==undefined?money(r.price):'—'}</td><td>${r.quantity!==''&&r.quantity!==undefined&&r.price!==''&&r.price!==undefined?money(Number(r.quantity)*Number(r.price)):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="5">Total anggaran kegiatan</td><td><b>${money(a.budget)}</b></td></tr></tfoot></table></div></details>`}
function savedPlanOverview(id,acts){const i=ind(id);return `<article class="card guided-plan saved-plan layered-summary" id="plan-${id}"><header class="guided-header"><span class="tag">Prioritas perbaikan</span><h2>${esc(i.name)}</h2>${indicatorTargetContext(id)}</header><div class="saved-activities"><div class="row saved-list-heading"><h3>Kegiatan yang direncanakan</h3><span class="sub">${acts.length} kegiatan</span></div>${acts.map((a,j)=>`<section class="saved-activity"><h3>${j+1}. ${esc(activitySummaryTitle(a))}</h3><p class="sub">Menjawab: ${esc(a.root)}</p><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation)}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</section>`).join('')}</div><footer class="hierarchy-footer"><span>✓ Rencana prioritas tersimpan</span><button onclick="editSavedPlan('${id}')">Ubah rencana</button></footer></article>`}

function editSavedPlan(id){data.planSaved={...data.planSaved,[id]:false};plannerOpen[id]=0;save();render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'})}


function reviewCards(readOnly=false){return data.priorities.map((id,index)=>{const i=ind(id),acts=data.activities.filter(a=>a.indicator===id);return `<article class="card review-flow-card"><div class="review-flow-head"><span class="hierarchy-eyebrow">Menetapkan · Prioritas ${index+1}</span><h2>${esc(i.name)}</h2><p class="source-text">${esc(i.code)} · ${esc(i.source)} · Periode ${esc(i.period)}</p>${indicatorTargetContext(id)}${readOnly?'':`<button class="review-edit" onclick="editFromReview('${id}','target')">Ubah target</button>`}</div><div class="review-flow-body"><section class="review-chain"><div><div class="row review-chain-title"><h3>Memetakan · Akar masalah yang dipilih</h3>${readOnly?'':`<button class="review-edit" onclick="editFromReview('${id}','roots')">Ubah</button>`}</div>${(data.roots[id]||[]).map(root=>`<p class="review-root">${esc(root)}</p>`).join('')}</div></section><div class="review-planned-activities"><h3>Merencanakan · Kegiatan yang direncanakan</h3>${acts.map((activity,j)=>`<section class="review-aligned-activity"><div class="row"><h4>${j+1}. ${esc(activitySummaryTitle(activity))}</h4>${readOnly?'':`<button class="review-edit" onclick="editFromReview('${id}','activity','${activity.id}')">Ubah kegiatan</button>`}</div><p class="source-text">Menjawab: ${esc(activity.root)}</p><div class="review-activity-columns"><div class="review-implementation-column"><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(activity.implementation||'Belum diisi')}</p></div>${activity.recommendationKey?`<details class="saved-recommendation"><summary>Lihat teks rekomendasi lengkap</summary><p>${esc(activity.name)}</p></details>`:''}</div><aside class="review-budget-column"><span class="review-budget-label">Anggaran kegiatan</span><p>${activityBudgetSummary(activity)}</p>${savedActivityBudgetDetails(activity)}</aside></div></section>`).join('')}</div></div><div class="review-flow-footer"><span>${acts.length} kegiatan · Total anggaran terisi <b>${money(acts.reduce((sum,a)=>sum+Number(a.budget||0),0))}</b></span></div></article>`}).join('')}

function editFromReview(id,part,activityId){if(!['Draf','Perlu revisi'].includes(data.status))return toast('Rencana telah disimpan sebagai acuan pelaksanaan.');if(part==='target'){requestPriorityTarget(id);return}if(part==='roots'){stage=1;go('flow');document.getElementById('root-card-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});return}data.planSaved={...data.planSaved,[id]:false};plannerOpen[id]=part==='target'?0:part==='success'?2:1;stage=2;save();go('flow');document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});const fieldId=activityId+'-implementation';document.getElementById(fieldId)?.focus({preventScroll:true})}

function budgetReview(readOnly=false){const funded=data.activities.filter(a=>a.needsBudget===true||Number(a.budget)>0),total=funded.reduce((sum,a)=>sum+Number(a.budget||0),0);return `<section class="card budget-review"><div class="row"><div><span class="hierarchy-eyebrow">Tinjauan anggaran</span><h2>Rincian anggaran untuk ARKAS</h2><p class="sub">Rangkuman kebutuhan anggaran dari kegiatan yang direncanakan. Rincian yang belum diisi tetap bersifat opsional.</p></div><span class="badge blue">${funded.length} kegiatan membutuhkan anggaran</span></div>${funded.length?funded.map(a=>`<section class="review-aligned-activity"><div class="row"><h3>${esc(activitySummaryTitle(a))}</h3>${readOnly?'':`<button class="review-edit" onclick="editFromReview('${a.indicator}','budget','${a.id}')">Ubah</button>`}</div><p class="sub">Prioritas: ${esc(ind(a.indicator).name)}</p><p>${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</section>`).join(''):'<p class="sub">Tidak ada kegiatan yang ditandai membutuhkan anggaran.</p>'}<p>Total anggaran terisi: <b>${money(total)}</b></p>${!readOnly&&funded.some(a=>Number(a.budget)>0)?'<label class="check"><input id="budget-confirm" type="checkbox"><span>Saya telah meninjau rincian anggaran yang terisi untuk disampaikan ke ARKAS.</span></label>':''}<p class="source-text">Prototipe ini belum mengirim data ke ARKAS. Persetujuan anggaran dan rencana dilakukan terpisah.</p></section>`}


function listRktStatus(rkt){if(rkt.status==='Selesai')return 'Selesai';if(rkt.evaluationSubmitted)return 'Tindak lanjut belum selesai';if(rkt.evaluationOpen)return 'Masa evaluasi';return rkt.status==='Sudah ada rencana'||Object.values(rkt.planSaved||{}).some(Boolean)?'Sudah ada rencana':'Draf'}

function approvedRktView(){return `<button class="quiet" onclick="go('home')">← Kembali ke daftar RKT</button><div class="flow-heading"><div><div class="eyebrow">Rencana Kerja Tahunan · ${esc(data.year)}</div><h1>Rencana perbaikan sekolah</h1><p class="muted">${period()} · SMA Merdeka Belajar 1</p></div><div class="document-status">${badge(data.status==='Sudah ada rencana'?'Sudah ada rencana':data.status==='Selesai'?'Selesai':listRktStatus(data))}<span class="sub">Hanya dapat dilihat</span></div></div><div class="notice approved-notice">${data.status==='Sudah ada rencana'?'Rencana telah disimpan dan menjadi acuan pelaksanaan. Perbarui capaian melalui tombol Masukkan capaian pada daftar siklus.':data.status==='Selesai'?'Siklus RKT ini telah selesai. Rencana tersimpan sebagai arsip sekolah.':'Ringkasan rencana beserta rincian anggaran. Halaman ini hanya dapat dilihat.'}</div><section class="flow-content">${reviewCards(true)}${budgetReview(true)}<div class="card approved-total"><span>${data.priorities.length} prioritas · ${data.activities.length} kegiatan</span><b>Total anggaran: ${money(data.activities.reduce((sum,a)=>sum+Number(a.budget||0),0))}</b></div></section>`}
function openExecution(){if(data.status!=='Sudah ada rencana')return toast('Simpan rencana prioritas terlebih dahulu.');stage=3;go('flow')}

document.addEventListener('click',event=>{if(!event.target.closest('.row-overflow'))document.querySelectorAll('.row-overflow[open]').forEach(el=>el.open=false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.row-overflow[open]').forEach(el=>{el.open=false;el.querySelector('summary').focus()})});


let menetapkanFilter='Rekomendasi Indikator',menetapkanSource='Semua sumber';
let menetapkanReminderDismissed=false;
function dismissMenetapkanReminder(button){menetapkanReminderDismissed=true;button.closest('.menetapkan-recommendation-reminder')?.remove()}
function menetapkanRecommendationReminder(){return menetapkanFilter==='Rekomendasi Indikator'&&!menetapkanReminderDismissed?`<aside class="menetapkan-recommendation-reminder" aria-label="Pengingat rekomendasi indikator"><p>List ini hanya rekomendasi berdasarkan dari capaian tahun lalu. Namun, sekolah bisa memilih indikator yang lebih sesuai dengan kondisi saat ini.</p><button type="button" aria-label="Tutup pengingat rekomendasi" onclick="dismissMenetapkanReminder(this)">×</button></aside>`:''}

function openMenetapkanAlternative(){prepareDemo();stage=0;menetapkanFilter='Rekomendasi Indikator';menetapkanSource='Semua sumber';save();go('menetapkan-alternative')}
function setMenetapkanFilter(value){menetapkanFilter=value;render()}
function menetapkanTabBadge(name,recommended){const count=indicators.filter(i=>data.priorities.includes(i.id)&&(name==='Rekomendasi Indikator'?recommended.has(i.id):dimensionOf(i)===name)).length;return count?`<span class="menetapkan-tab-count" aria-label="${count} indikator dipilih">${count}</span>`:''}
function menetapkanAlternative(){const top=new Set(['lit','num','A.3','D.4','D.8','ajar','tka2']);if(!['Rekomendasi Indikator',...dimensionNames].includes(menetapkanFilter))menetapkanFilter='Rekomendasi Indikator';const visible=indicators.filter(i=>menetapkanFilter==='Rekomendasi Indikator'?top.has(i.id):dimensionOf(i)===menetapkanFilter).sort(compareIndicatorAchievement);return `<button class="quiet" onclick="go('home')">← Kembali ke daftar siklus</button>${steps()}<div class="priority-selection-bar" role="status" aria-live="polite" aria-atomic="true"><div><strong>${data.priorities.length} indikator sudah dipilih</strong><span>Pilih 2–3 indikator sesuai kebutuhan murid.</span></div><div class="priority-bar-actions"><button onclick="save();go('home')">Simpan draf & keluar</button><button class="primary" onclick="next()">Lanjutkan →</button></div></div><div class="report-group-filters diagnosis-dimension-tabs menetapkan-dimension-tabs" role="group" aria-label="Filter indikator Menetapkan">${['Rekomendasi Indikator',...dimensionNames].map(name=>`<button aria-pressed="${menetapkanFilter===name}" onclick="setMenetapkanFilter('${name}')">${esc(name)}${menetapkanTabBadge(name,top)}</button>`).join('')}</div><div class="report-list-toolbar"><p class="sub" role="status">${visible.length} indikator ditampilkan</p></div>${menetapkanRecommendationReminder()}<div class="diagnosis-reference-grid menetapkan-reference-grid">${visible.map(i=>diagnosisReferenceCard(i,true)).join('')||'<p class="muted source-filter-empty">Belum ada indikator untuk kelompok yang dipilih.</p>'}</div>${reportDialog()}`}

function priorityReferenceFooter(i){const selected=data.priorities.includes(i.id);return `<button class="${selected?'priority-selected':''}" aria-pressed="${selected}" onclick="choose('${i.id}',${!selected})">${selected?'Batalkan':'Pilih'}</button>${selected?`<p class="priority-card-target">Target: <b>${esc(data.targets[i.id]??'—')} ${esc(i.unit)}</b><button class="quiet" onclick="requestPriorityTarget('${i.id}')">Ubah target</button></p>`:''}`}

function indicatorSourceLabel(i){if(i.source==='Rapor Pendidikan')return 'Rapor';if(/akreditasi/i.test(i.source+' '+i.origin))return 'Akreditasi';return i.source}
function setMenetapkanSource(value){menetapkanSource=value;render()}

function legacyMenetapkan(){return `<button class="quiet" onclick="go('home')">← Kembali ke daftar siklus</button>${steps()}<div class="priority-layout"><section class="flow-content">${priorities()}</section>${chosenPanel()}</div>`}

function editCurrentPlan(){if(listRktStatus(data)!=='Sudah ada rencana'||data.status==='Selesai')return;stage=2;go('flow')}

function localDesignAlternatives(){return typeof location!=='undefined'&&['localhost','127.0.0.1','[::1]'].includes(location.hostname)}

function diagnosisSummary(){return `<section class="diagnosis-school-summary" aria-label="Identitas sekolah"><div><p class="diagnosis-summary-label">Rapor Pendidikan</p><h2>SMA Rakyat 3</h2><dl><dt>NPSN</dt><dd>20260001</dd><dt>Alamat</dt><dd>Jl. Merdeka No. 12, Kec. Menteng</dd><dt>Kota/Provinsi</dt><dd>Kota Jakarta Pusat, DKI Jakarta</dd></dl></div><div class="diagnosis-school-side"><div class="diagnosis-year-picker"><span class="year-select-label" id="diagnosis-data-year-label">Pilih Tahun Data</span><div class="year-select"><button type="button" class="year-select-trigger" id="diagnosis-data-year" aria-haspopup="listbox" aria-expanded="false" aria-labelledby="diagnosis-data-year-label diagnosis-data-year"><span class="year-select-value">2025</span><svg class="year-select-caret" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10l5 5 5-5z"/></svg></button><ul class="year-select-list" role="listbox" aria-labelledby="diagnosis-data-year-label" hidden><li role="option" aria-selected="true" data-year="2025">2025</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2024">2024</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2023">2023</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2022">2022</li></ul></div></div><div class="diagnosis-accreditation"><b><svg class="accreditation-info" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/></svg>Akreditasi</b><span class="accreditation-badge" aria-label="Akreditasi A">A</span></div></div></section><section class="diagnosis-overview-banner" aria-labelledby="diagnosis-overview-title"><h2 id="diagnosis-overview-title">Ringkasan kondisi Satuan Pendidikan Anda berdasarkan Rapor Pendidikan Tahun 2025</h2><div class="diagnosis-highlight-grid"><article><img class="diagnosis-highlight-icon" src="assets/icons/peningkatan-tertinggi.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Peningkatan Tertinggi</p><h3>Iklim keamanan satuan pendidikan</h3></div></article><article><img class="diagnosis-highlight-icon" src="assets/icons/capaian-terbaik.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Capaian Terbaik</p><h3>Karakter</h3></div></article><article><img class="diagnosis-highlight-icon" src="assets/icons/capaian-terendah.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Capaian Terendah</p><h3>Kemampuan literasi</h3></div></article></div><div class="diagnosis-improvement-tip"><img src="assets/icons/emoji-objects.svg" width="24" height="24" alt="" aria-hidden="true"><div><p>Contoh cara membenahi Kemampuan Literasi</p><b>Kemampuan untuk memahami teks informasi berkaitan erat dengan kemampuan literasi siswa secara keseluruhan.</b></div></div><div class="diagnosis-overview-actions"><button onclick="document.getElementById('report-indicators').scrollIntoView({behavior:'smooth',block:'start'})">Lihat Seluruh Capaian Satdik Saya ↓</button><p>Perlu panduan? <button class="diagnosis-guide-link" onclick="go('help')">Lihat cara menggunakan Rapor Pendidikan & PBD</button></p></div></section>`}

function setDiagnosisSource(value){if(!['Rapor Pendidikan','TKA','Akreditasi'].includes(value))return;diagnosisSource=value;updateDiagnosisFilters()}

function compareIndicatorAchievement(a,b){const rank=i=>{if(typeof i.score!=='number'||!Number.isFinite(i.score))return 3;const label=String(i.level||'').toLowerCase();return label.startsWith('kurang')?0:label.startsWith('sedang')?1:label.startsWith('baik')?2:3};const difference=rank(a)-rank(b);if(difference)return difference;const aScore=typeof a.score==='number'&&Number.isFinite(a.score)?a.score:Infinity,bScore=typeof b.score==='number'&&Number.isFinite(b.score)?b.score:Infinity;if(aScore!==bScore)return aScore-bScore;return String(a.code).localeCompare(String(b.code),'id',{numeric:true})}
function diagnosisVisibleIndicators(){return indicators.filter(i=>(reportGroupFilter==='Semua'||dimensionOf(i)===reportGroupFilter)&&(diagnosisSource==='Akreditasi'?indicatorSourceLabel(i)==='Akreditasi':i.source===diagnosisSource)).sort(compareIndicatorAchievement)}
function diagnosisResultsMarkup(items){return items.length?`<div class="diagnosis-reference-grid">${items.map(i=>diagnosisReferenceCard(i)).join('')}</div>`:'<div class="card empty"><p class="muted">Belum ada data indikator untuk sumber dan dimensi yang dipilih.</p></div>'}
function updateDiagnosisFilters(){const results=document.getElementById('diagnosis-results');if(!results){render();return}const position=window.scrollY;const requiredHeight=Math.max(0,window.innerHeight-results.getBoundingClientRect().top);results.style.minHeight=requiredHeight+'px';document.querySelectorAll('[data-diagnosis-dimension]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.diagnosisDimension===reportGroupFilter)));document.querySelectorAll('[data-diagnosis-source]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.diagnosisSource===diagnosisSource)));const visible=diagnosisVisibleIndicators();document.getElementById('diagnosis-result-count').textContent=visible.length+' indikator ditampilkan';results.innerHTML=diagnosisResultsMarkup(visible);window.scrollTo({top:position,left:0,behavior:'instant'})}
function openMenetapkanCards(){prepareDemo();data.activities=[];stage=0;menetapkanFilter='Rekomendasi Indikator';save();go('menetapkan-cards')}
function scrollToSelectedIndicator(id){if(!data.priorities.includes(id))return;let row=document.getElementById('menetapkan-row-'+id);if(!row){menetapkanFilter=dimensionOf(ind(id));render();row=document.getElementById('menetapkan-row-'+id)}if(row){row.focus({preventScroll:true});row.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center',inline:'nearest'})}}
function menetapkanSelectionPanel(){return `<aside class="menetapkan-selection-panel card" aria-label="Indikator dipilih"><h3 class="menetapkan-selection-title">Indikator dipilih</h3><div class="menetapkan-selected-list">${data.priorities.map(id=>`<div class="menetapkan-selected-item"><button type="button" class="menetapkan-selected-link" onclick="scrollToSelectedIndicator('${id}')">${esc(ind(id).name)}</button><button class="quiet" aria-label="Hapus prioritas ${esc(ind(id).name)}" onclick="choose('${id}',false)">×</button></div>`).join('')||'<p class="sub">Belum ada indikator yang dipilih.</p>'}</div><div class="menetapkan-selection-actions"><button class="primary" onclick="next()">Lanjutkan →</button><button onclick="save();go('home')">Simpan draf & keluar</button></div></aside>`}
function menetapkanTablePage(){let html=menetapkanAlternative();const barStart=html.indexOf('<div class="priority-selection-bar"'),barEnd=html.indexOf('<div class="report-group-filters',barStart);html=html.slice(0,barStart)+html.slice(barEnd);const start=html.indexOf('<div class="diagnosis-reference-grid menetapkan-reference-grid">'),end=html.indexOf('<dialog id="report-dialog"',start);const top=new Set(['lit','num','A.3','D.4','D.8','ajar','tka2']);const items=indicators.filter(i=>menetapkanFilter==='Rekomendasi Indikator'?top.has(i.id):dimensionOf(i)===menetapkanFilter).sort(compareIndicatorAchievement);const periods=[...new Set(items.map(i=>String(i.period)).filter(p=>/^20\d{2}$/.test(p)))];const unknown=items.some(i=>!/^20\d{2}$/.test(String(i.period)));const note=periods.length?'Skor capaian diambil dari tahun data '+periods.join(', ')+(unknown?'; sebagian sumber belum mencantumkan tahun.':'.'):'Tahun data skor capaian belum dicantumkan oleh sumber.';return (html.slice(0,start)+`<div class="menetapkan-table-layout"><section class="menetapkan-table-content" aria-label="Daftar indikator">${menetapkanTable(items)}</section>${menetapkanSelectionPanel()}</div>`+html.slice(end)).replace(' indikator ditampilkan</p>',' indikator ditampilkan</p><p class="sub table-data-year-note">'+esc(note)+'</p>')}
function menetapkanTable(items){return `<div class="menetapkan-table-scroll"><table class="menetapkan-indicator-table"><thead><tr><th scope="col">Indikator</th><th scope="col">Capaian awal</th><th scope="col">Perubahan dari 2024</th><th scope="col">Target ${esc(data.year)}</th><th scope="col">Prioritas</th></tr></thead><tbody>${items.map(i=>{const selected=data.priorities.includes(i.id);return `<tr id="menetapkan-row-${esc(i.id)}" tabindex="-1" class="${selected?'selected-indicator-row':''}"><td><span class="source-text">${esc(i.code)}</span><div class="table-indicator-title"><h3>${esc(i.name)}</h3><button type="button" class="indicator-description-tooltip" aria-label="Deskripsi ${esc(i.name)}" aria-controls="indicator-description-${esc(i.id)}" aria-expanded="false" onclick="toggleIndicatorDescription(this,'${i.id}')">ⓘ</button><div popover="auto" class="indicator-description-popover" id="indicator-description-${esc(i.id)}" role="note" ontoggle="document.querySelector('[aria-controls=&quot;indicator-description-${esc(i.id)}&quot;]')?.setAttribute('aria-expanded',String(this.matches(':popover-open')))">${esc(i.definition||i.desc||'Deskripsi belum tersedia.')}</div></div>${['Rapor','TKA','Akreditasi'].includes(indicatorSourceLabel(i))?`<p class="sub table-indicator-source">${esc(i.source)}</p>`:''}</td><td><div class="table-achievement"><span class="badge ${typeof i.score==='number'?esc(i.color):''}">${esc(i.level||'Belum tersedia')}</span><strong class="table-baseline">${scoreText(i)} ${esc(i.unit)}</strong></div></td><td class="table-indicator-change">${reportDelta(i).replace('Capaian ','').replace('class="muted"','class="table-no-comparison"')}</td><td>${selected?`<strong>${esc(data.targets[i.id]??'—')} ${esc(i.unit)}</strong><button class="quiet table-target-edit" onclick="requestPriorityTarget('${i.id}')">Ubah target</button>`:'<span class="sub">Pilih sebagai prioritas untuk menetapkan target</span>'}</td><td><button class="${selected?'table-priority-selected':'primary'}" aria-pressed="${selected}" aria-label="${selected?'Batalkan':'Pilih'} ${esc(i.name)}" onclick="choose('${i.id}',${!selected})">${selected?'Batalkan':'Pilih'}</button></td></tr>`}).join('')||'<tr><td colspan="5">Belum ada indikator untuk kelompok yang dipilih.</td></tr>'}</tbody></table></div>`}

function toggleIndicatorDescription(button,id){const popover=document.getElementById('indicator-description-'+id);if(popover.matches(':popover-open')){popover.hidePopover();return}popover.showPopover();const rect=button.getBoundingClientRect(),box=popover.getBoundingClientRect();popover.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-box.width-12))+'px';popover.style.top=(rect.bottom+8+box.height<=window.innerHeight-12?rect.bottom+8:Math.max(12,rect.top-box.height-8))+'px'}

function budgetMonths(value){return Array.isArray(value)?value:typeof value==='string'?value.split(',').map(m=>m.trim()).filter(Boolean):[]}
function budgetMonthPicker(id,index,value){const selected=budgetMonths(value);return `<div class="budget-month-picker"><button type="button" class="budget-month-trigger" aria-label="Bulan Dianggarkan ${index+1}" aria-expanded="false" aria-controls="budget-month-${id}-${index}" onclick="toggleBudgetMonthPopover(this,'${id}',${index})">${selected.length?esc(selected.join(', ')):'Pilih bulan'}</button><div popover="auto" id="budget-month-${id}-${index}" ontoggle="document.querySelector('[aria-controls=&quot;budget-month-${id}-${index}&quot;]')?.setAttribute('aria-expanded',String(this.matches(':popover-open')))" class="budget-month-options" role="group" aria-label="Bulan dianggarkan"><p class="budget-month-hint">Bisa pilih lebih dari satu</p>${['Jul','Agu','Sep','Okt','Nov','Des','Jan','Feb','Mar','Apr','Mei','Jun'].map(m=>`<label><input type="checkbox" value="${m}" ${selected.includes(m)?'checked':''} onchange="updateBudgetMonths('${id}',${index},this)"><span>${m}</span></label>`).join('')}</div></div>`}
function updateBudgetMonths(id,index,input){const picker=input.closest('.budget-month-picker');const selected=[...picker.querySelectorAll('input:checked')].map(el=>el.value);updateBudgetLine(id,index,'month',selected.join(', '));picker.querySelector('.budget-month-trigger').textContent=selected.length?selected.join(', '):'Pilih bulan'}

function toggleBudgetMonthPopover(button,id,index){const panel=document.getElementById('budget-month-'+id+'-'+index);if(panel.matches(':popover-open')){panel.hidePopover();return}panel.showPopover();const rect=button.getBoundingClientRect();panel.style.width=Math.min(260,window.innerWidth-24)+'px';const box=panel.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-box.width-12))+'px';panel.style.top=(rect.bottom+6+box.height<=window.innerHeight-12?rect.bottom+6:Math.max(12,rect.top-box.height-6))+'px'}

/* Ikon Material (set yang sama dengan Figma Rapor Pendidikan) menggantikan karakter teks ←→↑↓↗⌄✓ⓘ */
(function(){
  var P={'←':'M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z','→':'M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z','↑':'M4 12l1.41 1.41L11 7.83V20h2V7.83l5.58 5.59L20 12l-8-8-8 8z','↓':'M20 12l-1.41-1.41L13 16.17V4h-2v12.17l-5.58-5.59L4 12l8 8 8-8z','↗':'M6 6v2h8.59L5 17.59 6.41 19 16 9.41V18h2V6z','⌄':'M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z','✓':'M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z','ⓘ':'M11 7h2v2h-2zm0 4h2v6h-2zm1-9C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z'};
  var re=/[←→↑↓↗⌄✓ⓘ]/, split=/([←→↑↓↗⌄✓ⓘ])/, skip={SCRIPT:1,STYLE:1,TEXTAREA:1,OPTION:1,TITLE:1};
  function icon(g){var s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('class','ic');s.setAttribute('aria-hidden','true');var p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',P[g]);s.appendChild(p);return s}
  function convert(root){
    var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),list=[];
    while(w.nextNode()){var n=w.currentNode;if(re.test(n.nodeValue)&&!skip[n.parentNode.nodeName])list.push(n)}
    list.forEach(function(n){var f=document.createDocumentFragment();n.nodeValue.split(split).forEach(function(t){if(P[t])f.appendChild(icon(t));else if(t)f.appendChild(document.createTextNode(t))});n.replaceWith(f)})
  }
  var obs=new MutationObserver(function(){obs.disconnect();convert(document.body);obs.observe(document.body,{childList:true,subtree:true,characterData:true})});
  function start(){convert(document.body);obs.observe(document.body,{childList:true,subtree:true,characterData:true})}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();

/* Dropdown Tahun Data (Seragam Select + Popover): daftar kustom agar tampil sama dengan Figma */
(function(){
  function close(root){var t=root.querySelector('.year-select-trigger'),l=root.querySelector('.year-select-list');if(!t||!l)return;l.hidden=true;t.setAttribute('aria-expanded','false')}
  function open(root){var t=root.querySelector('.year-select-trigger'),l=root.querySelector('.year-select-list');l.hidden=false;t.setAttribute('aria-expanded','true')}
  document.addEventListener('click',function(e){
    var root=e.target.closest&&e.target.closest('.year-select');
    document.querySelectorAll('.year-select').forEach(function(r){if(r!==root)close(r)});
    if(!root)return;
    var opt=e.target.closest('[role=option]');
    if(opt){if(opt.getAttribute('aria-disabled')==='true')return;root.querySelectorAll('[role=option]').forEach(function(o){o.setAttribute('aria-selected',String(o===opt))});root.querySelector('.year-select-value').textContent=opt.dataset.year;close(root);root.querySelector('.year-select-trigger').focus();return}
    if(e.target.closest('.year-select-trigger')){var l=root.querySelector('.year-select-list');l.hidden?open(root):close(root)}
  });
  document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.year-select').forEach(close)});
})();
